-- ---------- 0001_extensions_enums.sql ----------
-- =====================================================================
-- 0001_extensions_enums.sql
-- TravelHub Gulf — foundational extensions, schemas and enumerations.
-- =====================================================================

create extension if not exists "pgcrypto";       -- gen_random_uuid()
create extension if not exists "pg_trgm";        -- fuzzy search / autocomplete
create extension if not exists "unaccent";       -- accent-insensitive search (Arabic/Latin)
create extension if not exists "btree_gist";     -- exclusion constraints on ranges
create extension if not exists "postgis";       -- geospatial "near me" queries
create extension if not exists "citext";         -- case-insensitive emails
create extension if not exists "ltree";          -- category tree paths
create extension if not exists "pg_stat_statements";

-- Internal helper namespace: never exposed through PostgREST.
create schema if not exists internal;
revoke all on schema internal from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Identity & access
-- ---------------------------------------------------------------------
create type user_role as enum (
  'traveler', 'company_owner', 'company_staff', 'editor', 'support', 'admin', 'super_admin'
);

create type company_status as enum ('pending', 'active', 'suspended', 'rejected', 'archived');
create type verification_tier as enum ('none', 'verified', 'premium', 'elite');

-- ---------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------
create type listing_status as enum ('draft', 'in_review', 'published', 'paused', 'rejected', 'archived');
create type tour_type as enum ('private', 'group', 'self_guided', 'ticket_only', 'transfer', 'multi_day');
create type confirmation_type as enum ('instant', 'manual', 'on_request');
create type cancellation_policy as enum ('flexible_24h', 'moderate_48h', 'standard_72h', 'strict', 'non_refundable');
create type pax_type as enum ('adult', 'child', 'infant', 'senior', 'student', 'group', 'vehicle');
create type day_part as enum ('morning', 'afternoon', 'evening', 'night', 'full_day');

-- ---------------------------------------------------------------------
-- Commerce
-- ---------------------------------------------------------------------
create type booking_status as enum (
  'pending', 'awaiting_payment', 'confirmed', 'on_hold', 'completed',
  'cancelled_by_user', 'cancelled_by_supplier', 'expired', 'no_show'
);
create type payment_status as enum ('initiated', 'authorized', 'captured', 'partially_refunded', 'refunded', 'failed', 'disputed');
create type payment_provider as enum ('stripe', 'paypal', 'apple_pay', 'google_pay', 'tap', 'hyperpay', 'telr', 'network_intl', 'wallet', 'bank_transfer', 'cash_on_arrival');
create type payout_status as enum ('scheduled', 'processing', 'paid', 'failed', 'on_hold');
create type discount_type as enum ('percentage', 'fixed_amount', 'free_pax');
create type wallet_txn_type as enum ('topup', 'booking_payment', 'refund', 'reward', 'referral', 'adjustment', 'expiry');

-- ---------------------------------------------------------------------
-- Content, SEO & monetization
-- ---------------------------------------------------------------------
create type content_status as enum ('draft', 'scheduled', 'published', 'archived');
create type review_status as enum ('pending', 'published', 'rejected', 'flagged');
create type ad_placement as enum (
  'home_hero', 'home_billboard', 'search_inline', 'listing_sidebar', 'tour_detail',
  'category_top', 'blog_native', 'newsletter', 'popup', 'sticky_footer'
);
create type ad_pricing_model as enum ('cpm', 'cpc', 'flat_monthly', 'flat_weekly');
create type feature_slot as enum ('homepage', 'country', 'city', 'category', 'search_top', 'top_picks', 'related');
create type media_kind as enum ('image', 'video', 'virtual_tour', 'document');

-- ---------------------------------------------------------------------
-- i18n — one enum keeps locale integrity across every translation table.
-- ---------------------------------------------------------------------
create type locale_code as enum ('en', 'ar', 'hi', 'ur', 'fr', 'ru', 'de', 'zh');
create type currency_code as enum ('AED', 'SAR', 'QAR', 'OMR', 'BHD', 'KWD', 'USD', 'EUR', 'GBP', 'INR', 'PKR');

-- ---------------------------------------------------------------------
-- Shared trigger: keep updated_at honest without trusting the client.
-- ---------------------------------------------------------------------
create or replace function internal.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- Slugify helper used by translation tables and programmatic SEO routes.
create or replace function internal.slugify(input text)
returns text
language sql
immutable
as $$
  select trim(both '-' from
    regexp_replace(
      lower(public.unaccent('public.unaccent'::regdictionary, coalesce(input, ''))),
      '[^a-z0-9\u0600-\u06FF\u0900-\u097F]+', '-', 'g'
    )
  );
$$;

-- ---------- 0002_geography_identity.sql ----------
-- =====================================================================
-- 0002_geography_identity.sql
-- Destinations (the SEO backbone), user profiles and supplier companies.
-- =====================================================================

-- ---------------------------------------------------------------------
-- GEOGRAPHY
-- Countries > cities > areas > points of interest.
-- Every level is independently indexable => programmatic SEO surface.
-- ---------------------------------------------------------------------
create table countries (
  id            uuid primary key default gen_random_uuid(),
  iso2          char(2) not null unique,
  iso3          char(3) not null unique,
  dial_code     text not null,
  currency      currency_code not null,
  timezone      text not null,
  centroid      geography(point, 4326) not null,
  bounds        geography(polygon, 4326),
  flag_emoji    text,
  is_active     boolean not null default true,
  is_launched   boolean not null default false,   -- controls sitemap inclusion
  priority      smallint not null default 0,      -- editorial ordering
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table country_translations (
  country_id        uuid not null references countries(id) on delete cascade,
  locale            locale_code not null,
  name              text not null,
  slug              text not null,
  tagline           text,
  intro             text,                          -- 120-200 words, above the fold
  body              text,                          -- long-form destination guide
  meta_title        text,
  meta_description  text,
  primary key (country_id, locale)
);
create unique index country_slug_uq on country_translations (locale, slug);

create table cities (
  id             uuid primary key default gen_random_uuid(),
  country_id     uuid not null references countries(id) on delete restrict,
  centroid       geography(point, 4326) not null,
  timezone       text not null,
  population     integer,
  is_active      boolean not null default true,
  is_featured    boolean not null default false,
  priority       smallint not null default 0,
  hero_image_url text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index cities_country_idx on cities (country_id) where is_active;
create index cities_centroid_gix on cities using gist (centroid);

create table city_translations (
  city_id           uuid not null references cities(id) on delete cascade,
  locale            locale_code not null,
  name              text not null,
  slug              text not null,
  tagline           text,
  intro             text,
  body              text,
  best_time_to_visit text,
  getting_around    text,
  meta_title        text,
  meta_description  text,
  primary key (city_id, locale)
);
create unique index city_slug_uq on city_translations (locale, slug);

create table areas (
  id          uuid primary key default gen_random_uuid(),
  city_id     uuid not null references cities(id) on delete cascade,
  centroid    geography(point, 4326) not null,
  radius_m    integer not null default 3000,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now()
);
create index areas_city_idx on areas (city_id);

create table area_translations (
  area_id  uuid not null references areas(id) on delete cascade,
  locale   locale_code not null,
  name     text not null,
  slug     text not null,
  intro    text,
  primary key (area_id, locale)
);
create unique index area_slug_uq on area_translations (locale, slug);

-- Attractions, restaurants and hotels power the "nearby" modules on tour pages.
create table points_of_interest (
  id           uuid primary key default gen_random_uuid(),
  city_id      uuid not null references cities(id) on delete cascade,
  area_id      uuid references areas(id) on delete set null,
  kind         text not null check (kind in ('attraction','restaurant','hotel','landmark','mall','beach','park','museum')),
  location     geography(point, 4326) not null,
  address      text,
  rating       numeric(2,1) check (rating between 0 and 5),
  external_ref jsonb not null default '{}'::jsonb,  -- {google_place_id, mapbox_id, ...}
  image_url    text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now()
);
create index poi_location_gix on points_of_interest using gist (location);
create index poi_city_kind_idx on points_of_interest (city_id, kind) where is_active;

create table poi_translations (
  poi_id   uuid not null references points_of_interest(id) on delete cascade,
  locale   locale_code not null,
  name     text not null,
  slug     text not null,
  summary  text,
  primary key (poi_id, locale)
);
create unique index poi_slug_uq on poi_translations (locale, slug);

-- ---------------------------------------------------------------------
-- CATEGORIES — self-referencing tree (Adventure > Desert > Dune Buggy)
-- ---------------------------------------------------------------------
create table categories (
  id          uuid primary key default gen_random_uuid(),
  parent_id   uuid references categories(id) on delete restrict,
  depth       smallint not null default 0,
  path        ltree,                                -- materialised tree path
  icon        text,
  hero_image_url text,
  is_active   boolean not null default true,
  is_featured boolean not null default false,
  priority    smallint not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index categories_parent_idx on categories (parent_id);

create table category_translations (
  category_id       uuid not null references categories(id) on delete cascade,
  locale            locale_code not null,
  name              text not null,
  slug              text not null,
  intro             text,
  body              text,
  meta_title        text,
  meta_description  text,
  primary key (category_id, locale)
);
create unique index category_slug_uq on category_translations (locale, slug);

-- ---------------------------------------------------------------------
-- IDENTITY — profiles mirror auth.users; never store passwords here.
-- ---------------------------------------------------------------------
create table profiles (
  id                uuid primary key references auth.users(id) on delete cascade,
  role              user_role not null default 'traveler',
  full_name         text,
  display_name      text,
  avatar_url        text,
  phone             text,
  phone_verified    boolean not null default false,
  preferred_locale  locale_code not null default 'en',
  preferred_currency currency_code not null default 'AED',
  country_id        uuid references countries(id) on delete set null,
  date_of_birth     date,
  marketing_opt_in  boolean not null default false,
  referral_code     text unique,
  referred_by       uuid references profiles(id) on delete set null,
  loyalty_points    integer not null default 0 check (loyalty_points >= 0),
  last_seen_at      timestamptz,
  deleted_at        timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index profiles_role_idx on profiles (role) where deleted_at is null;

-- Author identity for EEAT: bylines, credentials, destination expertise.
create table authors (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid references profiles(id) on delete set null,
  slug          text not null unique,
  name          text not null,
  headline      text,
  bio           text,
  avatar_url    text,
  credentials   text[] not null default '{}',
  expertise_city_ids uuid[] not null default '{}',
  social        jsonb not null default '{}'::jsonb,  -- {x, linkedin, instagram}
  is_active     boolean not null default true,
  created_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------
-- SUPPLIERS
-- ---------------------------------------------------------------------
create table companies (
  id                 uuid primary key default gen_random_uuid(),
  slug               text not null unique,
  legal_name         text not null,
  display_name       text not null,
  status             company_status not null default 'pending',
  verification       verification_tier not null default 'none',
  country_id         uuid not null references countries(id) on delete restrict,
  city_id            uuid references cities(id) on delete set null,
  logo_url           text,
  cover_url          text,
  about              text,
  contact_email      citext not null,
  contact_phone      text,
  whatsapp           text,
  website            text,
  trade_license_no   text,
  trade_license_url  text,
  tax_registration_no text,
  commission_rate    numeric(5,2) not null default 20.00 check (commission_rate between 0 and 100),
  payout_currency    currency_code not null default 'AED',
  payout_details     jsonb not null default '{}'::jsonb,   -- encrypted at the app layer
  stripe_account_id  text,
  rating_avg         numeric(3,2) not null default 0,
  rating_count       integer not null default 0,
  response_time_mins integer,
  onboarded_at       timestamptz,
  suspended_reason   text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index companies_status_idx on companies (status);
create index companies_city_idx on companies (city_id) where status = 'active';

create table company_members (
  company_id  uuid not null references companies(id) on delete cascade,
  profile_id  uuid not null references profiles(id) on delete cascade,
  role        user_role not null default 'company_staff',
  permissions text[] not null default '{}',   -- fine-grained: tours.write, payouts.read
  invited_by  uuid references profiles(id) on delete set null,
  accepted_at timestamptz,
  created_at  timestamptz not null default now(),
  primary key (company_id, profile_id)
);
create index company_members_profile_idx on company_members (profile_id);

create trigger touch_countries before update on countries for each row execute function internal.touch_updated_at();
create trigger touch_cities    before update on cities    for each row execute function internal.touch_updated_at();
create trigger touch_profiles  before update on profiles  for each row execute function internal.touch_updated_at();
create trigger touch_companies before update on companies for each row execute function internal.touch_updated_at();

-- Auto-provision a profile whenever Supabase Auth creates a user.
create or replace function internal.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  insert into public.profiles (id, full_name, avatar_url, referral_code)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1)),
    new.raw_user_meta_data->>'avatar_url',
    upper(substr(encode(gen_random_bytes(6), 'hex'), 1, 8))
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function internal.handle_new_user();

-- ---------- 0003_catalog.sql ----------
-- =====================================================================
-- 0003_catalog.sql
-- Tours/experiences, options (ticket types), pricing, and inventory.
-- Inventory is modelled as departures so capacity can be locked per row.
-- =====================================================================

create table tours (
  id                  uuid primary key default gen_random_uuid(),
  company_id          uuid not null references companies(id) on delete cascade,
  city_id             uuid not null references cities(id) on delete restrict,
  area_id             uuid references areas(id) on delete set null,
  primary_category_id uuid not null references categories(id) on delete restrict,
  status              listing_status not null default 'draft',
  tour_type           tour_type not null default 'group',
  confirmation        confirmation_type not null default 'instant',
  cancellation        cancellation_policy not null default 'moderate_48h',

  duration_minutes    integer not null check (duration_minutes > 0),
  duration_days       smallint not null default 1,
  min_pax             smallint not null default 1,
  max_pax             smallint,
  min_age             smallint,
  max_age             smallint,
  day_parts           day_part[] not null default '{}',

  meeting_point       geography(point, 4326),
  meeting_address     text,
  dropoff_address     text,
  pickup_included     boolean not null default false,
  pickup_radius_m     integer,
  wheelchair_accessible boolean not null default false,
  family_friendly     boolean not null default true,
  is_luxury           boolean not null default false,
  is_private          boolean not null default false,

  guide_locales       locale_code[] not null default '{en}',
  audio_guide_locales locale_code[] not null default '{}',

  -- Denormalised commercial fields: read-hot, written by triggers/jobs.
  base_currency       currency_code not null default 'AED',
  from_price          numeric(12,2) not null default 0,
  compare_at_price    numeric(12,2),
  discount_pct        smallint generated always as (
                        case when compare_at_price is null or compare_at_price <= 0 then 0
                             else floor(((compare_at_price - from_price) / compare_at_price) * 100)::smallint end
                      ) stored,
  rating_avg          numeric(3,2) not null default 0,
  rating_count        integer not null default 0,
  booking_count       integer not null default 0,
  view_count          integer not null default 0,
  popularity_score    numeric(10,4) not null default 0,   -- recomputed nightly

  published_at        timestamptz,
  rejected_reason     text,
  created_by          uuid references profiles(id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint tours_pax_range check (max_pax is null or max_pax >= min_pax)
);
create index tours_city_status_idx on tours (city_id, status) where status = 'published';
create index tours_company_idx on tours (company_id);
create index tours_category_idx on tours (primary_category_id) where status = 'published';
create index tours_popularity_idx on tours (popularity_score desc) where status = 'published';
create index tours_price_idx on tours (from_price) where status = 'published';
create index tours_meeting_gix on tours using gist (meeting_point);

-- Many-to-many: a desert safari lives in Adventure, Desert and Family.
create table tour_categories (
  tour_id     uuid not null references tours(id) on delete cascade,
  category_id uuid not null references categories(id) on delete cascade,
  primary key (tour_id, category_id)
);
create index tour_categories_category_idx on tour_categories (category_id);

create table tour_translations (
  tour_id           uuid not null references tours(id) on delete cascade,
  locale            locale_code not null,
  title             text not null,
  slug              text not null,
  summary           text,
  description       text,
  highlights        text[] not null default '{}',
  inclusions        text[] not null default '{}',
  exclusions        text[] not null default '{}',
  what_to_bring     text[] not null default '{}',
  know_before_you_go text,
  meeting_instructions text,
  cancellation_text text,
  meta_title        text,
  meta_description  text,
  translated_by     text not null default 'human' check (translated_by in ('human','ai','ai_reviewed')),
  primary key (tour_id, locale)
);
create unique index tour_slug_uq on tour_translations (locale, slug);

create table tour_itinerary (
  id          uuid primary key default gen_random_uuid(),
  tour_id     uuid not null references tours(id) on delete cascade,
  position    smallint not null,
  duration_minutes integer,
  poi_id      uuid references points_of_interest(id) on delete set null,
  location    geography(point, 4326),
  admission_included boolean not null default false,
  unique (tour_id, position)
);

create table tour_itinerary_translations (
  itinerary_id uuid not null references tour_itinerary(id) on delete cascade,
  locale       locale_code not null,
  title        text not null,
  description  text,
  primary key (itinerary_id, locale)
);

create table tour_faqs (
  id       uuid primary key default gen_random_uuid(),
  tour_id  uuid not null references tours(id) on delete cascade,
  position smallint not null default 0,
  source   text not null default 'supplier' check (source in ('supplier','ai','support','paa')),
  is_published boolean not null default true
);

create table tour_faq_translations (
  faq_id   uuid not null references tour_faqs(id) on delete cascade,
  locale   locale_code not null,
  question text not null,
  answer   text not null,
  primary key (faq_id, locale)
);

create table media_assets (
  id            uuid primary key default gen_random_uuid(),
  kind          media_kind not null default 'image',
  provider      text not null default 'cloudinary',
  public_id     text not null,
  url           text not null,
  width         integer,
  height        integer,
  duration_s    integer,
  blurhash      text,
  bytes         bigint,
  content_hash  text,                       -- dedupe identical uploads
  uploaded_by   uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now()
);
create unique index media_provider_public_id_uq on media_assets (provider, public_id);

create table tour_media (
  tour_id   uuid not null references tours(id) on delete cascade,
  media_id  uuid not null references media_assets(id) on delete cascade,
  position  smallint not null default 0,
  is_cover  boolean not null default false,
  alt_text  jsonb not null default '{}'::jsonb,  -- {"en": "...", "ar": "..."} — image SEO
  primary key (tour_id, media_id)
);
create unique index tour_single_cover_uq on tour_media (tour_id) where is_cover;

create table tour_pickup_points (
  id        uuid primary key default gen_random_uuid(),
  tour_id   uuid not null references tours(id) on delete cascade,
  poi_id    uuid references points_of_interest(id) on delete set null,
  label     text not null,
  location  geography(point, 4326) not null,
  window_minutes smallint not null default 30,
  surcharge numeric(10,2) not null default 0
);
create index tour_pickup_tour_idx on tour_pickup_points (tour_id);

-- ---------------------------------------------------------------------
-- OPTIONS & PRICING
-- A tour has options (Standard / Premium / Private transfer). Each option
-- prices per pax type. Price rules layer seasonal and group overrides.
-- ---------------------------------------------------------------------
create table tour_options (
  id              uuid primary key default gen_random_uuid(),
  tour_id         uuid not null references tours(id) on delete cascade,
  code            text not null,
  position        smallint not null default 0,
  duration_minutes integer,
  max_pax         smallint,
  is_private      boolean not null default false,
  is_active       boolean not null default true,
  unique (tour_id, code)
);

create table tour_option_translations (
  option_id   uuid not null references tour_options(id) on delete cascade,
  locale      locale_code not null,
  name        text not null,
  description text,
  primary key (option_id, locale)
);

create table tour_prices (
  id          uuid primary key default gen_random_uuid(),
  option_id   uuid not null references tour_options(id) on delete cascade,
  pax         pax_type not null,
  currency    currency_code not null default 'AED',
  net_price   numeric(12,2) not null check (net_price >= 0),  -- supplier receives
  list_price  numeric(12,2) not null check (list_price >= 0), -- traveler pays
  min_qty     smallint not null default 0,
  max_qty     smallint,
  unique (option_id, pax, currency)
);

-- Seasonal / weekend / early-bird overrides, resolved by highest priority.
create table price_rules (
  id           uuid primary key default gen_random_uuid(),
  option_id    uuid not null references tour_options(id) on delete cascade,
  pax          pax_type,
  valid_range  daterange not null,
  weekdays     smallint[] not null default '{0,1,2,3,4,5,6}',
  adjust_type  discount_type not null default 'percentage',
  adjust_value numeric(12,2) not null,
  priority     smallint not null default 0,
  is_active    boolean not null default true
);
create index price_rules_option_idx on price_rules (option_id) where is_active;

-- ---------------------------------------------------------------------
-- INVENTORY
-- Recurrence template -> materialised departures (the lockable rows).
-- ---------------------------------------------------------------------
create table tour_schedules (
  id            uuid primary key default gen_random_uuid(),
  tour_id       uuid not null references tours(id) on delete cascade,
  option_id     uuid references tour_options(id) on delete cascade,
  rrule         text not null,             -- iCal RRULE, e.g. FREQ=DAILY;BYHOUR=16
  start_time    time not null,
  capacity      integer not null check (capacity > 0),
  valid_range   daterange not null,
  timezone      text not null default 'Asia/Dubai',
  is_active     boolean not null default true,
  created_at    timestamptz not null default now()
);

create table tour_departures (
  id             uuid primary key default gen_random_uuid(),
  tour_id        uuid not null references tours(id) on delete cascade,
  option_id      uuid not null references tour_options(id) on delete cascade,
  schedule_id    uuid references tour_schedules(id) on delete set null,
  starts_at      timestamptz not null,
  local_date     date not null,
  capacity       integer not null check (capacity >= 0),
  seats_held     integer not null default 0 check (seats_held >= 0),
  seats_booked   integer not null default 0 check (seats_booked >= 0),
  price_override numeric(12,2),
  is_closed      boolean not null default false,
  updated_at     timestamptz not null default now(),
  constraint departures_capacity_not_exceeded check (seats_booked + seats_held <= capacity),
  unique (option_id, starts_at)
);
create index departures_lookup_idx on tour_departures (tour_id, local_date) where not is_closed;
create index departures_availability_idx on tour_departures (option_id, starts_at)
  where not is_closed;

create trigger touch_tours before update on tours for each row execute function internal.touch_updated_at();
create trigger touch_departures before update on tour_departures for each row execute function internal.touch_updated_at();

-- ---------- 0004_commerce.sql ----------
-- =====================================================================
-- 0004_commerce.sql
-- Carts/holds, bookings, payments, refunds, coupons, wallet, payouts.
-- Money is stored as numeric(12,2) in a stated currency, never as float.
-- =====================================================================

create table coupons (
  id               uuid primary key default gen_random_uuid(),
  code             citext not null unique,
  company_id       uuid references companies(id) on delete cascade,  -- null = platform-wide
  discount_type    discount_type not null default 'percentage',
  discount_value   numeric(12,2) not null check (discount_value > 0),
  max_discount     numeric(12,2),
  min_order_total  numeric(12,2) not null default 0,
  currency         currency_code,
  applies_to_tours uuid[] not null default '{}',
  applies_to_cities uuid[] not null default '{}',
  applies_to_categories uuid[] not null default '{}',
  starts_at        timestamptz not null default now(),
  ends_at          timestamptz,
  usage_limit      integer,
  usage_limit_per_user smallint not null default 1,
  used_count       integer not null default 0,
  first_order_only boolean not null default false,
  is_active        boolean not null default true,
  created_by       uuid references profiles(id) on delete set null,
  created_at       timestamptz not null default now()
);
create index coupons_active_idx on coupons (is_active, ends_at);

create table bookings (
  id               uuid primary key default gen_random_uuid(),
  reference        text not null unique,                 -- THG-8F3K2QD, shown to travelers
  profile_id       uuid references profiles(id) on delete set null,   -- null for guest checkout
  company_id       uuid not null references companies(id) on delete restrict,
  status           booking_status not null default 'pending',

  guest_email      citext not null,
  guest_name       text not null,
  guest_phone      text not null,
  guest_locale     locale_code not null default 'en',
  guest_country_id uuid references countries(id) on delete set null,

  currency         currency_code not null,
  subtotal         numeric(12,2) not null default 0,
  discount_total   numeric(12,2) not null default 0,
  fees_total       numeric(12,2) not null default 0,
  tax_total        numeric(12,2) not null default 0,
  grand_total      numeric(12,2) not null default 0,
  wallet_applied   numeric(12,2) not null default 0,
  amount_due       numeric(12,2) not null default 0,
  commission_total numeric(12,2) not null default 0,      -- platform revenue
  supplier_net     numeric(12,2) not null default 0,

  coupon_id        uuid references coupons(id) on delete set null,
  coupon_code      citext,

  hold_expires_at  timestamptz,                            -- seats released after this
  confirmed_at     timestamptz,
  cancelled_at     timestamptz,
  cancellation_reason text,
  completed_at     timestamptz,

  source           text not null default 'web' check (source in ('web','ios','android','api','affiliate','admin')),
  utm              jsonb not null default '{}'::jsonb,
  affiliate_ref    text,
  ip_country       char(2),
  idempotency_key  text,

  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint bookings_totals_non_negative check (grand_total >= 0 and amount_due >= 0)
);
create unique index bookings_idempotency_uq on bookings (idempotency_key) where idempotency_key is not null;
create index bookings_profile_idx on bookings (profile_id, created_at desc);
create index bookings_company_idx on bookings (company_id, created_at desc);
create index bookings_status_idx on bookings (status) where status in ('pending','awaiting_payment','on_hold');
create index bookings_hold_expiry_idx on bookings (hold_expires_at) where hold_expires_at is not null;

create table booking_items (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references bookings(id) on delete cascade,
  tour_id        uuid not null references tours(id) on delete restrict,
  option_id      uuid not null references tour_options(id) on delete restrict,
  departure_id   uuid not null references tour_departures(id) on delete restrict,
  starts_at      timestamptz not null,
  seats          integer not null check (seats > 0),
  pax_breakdown  jsonb not null,        -- {"adult": 2, "child": 1}
  unit_prices    jsonb not null,        -- {"adult": 250.00, "child": 150.00}
  line_subtotal  numeric(12,2) not null,
  line_discount  numeric(12,2) not null default 0,
  line_total     numeric(12,2) not null,
  commission_rate numeric(5,2) not null,
  pickup_point_id uuid references tour_pickup_points(id) on delete set null,
  pickup_note    text,
  supplier_ref   text,
  ticket_code    text,                  -- QR payload, issued on confirmation
  redeemed_at    timestamptz,
  created_at     timestamptz not null default now()
);
create index booking_items_booking_idx on booking_items (booking_id);
create index booking_items_departure_idx on booking_items (departure_id);
create index booking_items_tour_idx on booking_items (tour_id, starts_at);

create table booking_travelers (
  id           uuid primary key default gen_random_uuid(),
  item_id      uuid not null references booking_items(id) on delete cascade,
  pax          pax_type not null,
  full_name    text,
  age          smallint,
  passport_no  text,       -- encrypted at the app layer when required by the supplier
  nationality  char(2),
  notes        text
);

create table payments (
  id                uuid primary key default gen_random_uuid(),
  booking_id        uuid not null references bookings(id) on delete cascade,
  provider          payment_provider not null,
  status            payment_status not null default 'initiated',
  currency          currency_code not null,
  amount            numeric(12,2) not null check (amount >= 0),
  amount_captured   numeric(12,2) not null default 0,
  amount_refunded   numeric(12,2) not null default 0,
  provider_intent_id text,
  provider_charge_id text,
  provider_fee      numeric(12,2),
  card_brand        text,
  card_last4        char(4),
  failure_code      text,
  failure_message   text,
  raw_event         jsonb not null default '{}'::jsonb,
  authorized_at     timestamptz,
  captured_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create unique index payments_intent_uq on payments (provider, provider_intent_id) where provider_intent_id is not null;
create index payments_booking_idx on payments (booking_id);

-- Every webhook we accept is recorded once; replay attacks become no-ops.
create table payment_events (
  id           uuid primary key default gen_random_uuid(),
  provider     payment_provider not null,
  event_id     text not null,
  event_type   text not null,
  payload      jsonb not null,
  processed_at timestamptz,
  error        text,
  received_at  timestamptz not null default now(),
  unique (provider, event_id)
);

create table refunds (
  id            uuid primary key default gen_random_uuid(),
  booking_id    uuid not null references bookings(id) on delete cascade,
  payment_id    uuid references payments(id) on delete set null,
  amount        numeric(12,2) not null check (amount > 0),
  currency      currency_code not null,
  reason        text not null,
  policy_applied cancellation_policy,
  penalty_amount numeric(12,2) not null default 0,
  status        payment_status not null default 'initiated',
  provider_refund_id text,
  requested_by  uuid references profiles(id) on delete set null,
  approved_by   uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  completed_at  timestamptz
);

create table coupon_redemptions (
  id          uuid primary key default gen_random_uuid(),
  coupon_id   uuid not null references coupons(id) on delete cascade,
  booking_id  uuid not null references bookings(id) on delete cascade,
  profile_id  uuid references profiles(id) on delete set null,
  amount      numeric(12,2) not null,
  created_at  timestamptz not null default now(),
  unique (coupon_id, booking_id)
);
create index coupon_redemptions_profile_idx on coupon_redemptions (coupon_id, profile_id);

create table gift_cards (
  id             uuid primary key default gen_random_uuid(),
  code_hash      text not null unique,        -- store a hash, never the raw code
  last4          char(4) not null,
  currency       currency_code not null,
  initial_amount numeric(12,2) not null check (initial_amount > 0),
  balance        numeric(12,2) not null check (balance >= 0),
  purchased_by   uuid references profiles(id) on delete set null,
  recipient_email citext,
  message        text,
  expires_at     timestamptz,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now()
);

create table wallets (
  profile_id  uuid primary key references profiles(id) on delete cascade,
  currency    currency_code not null default 'AED',
  balance     numeric(12,2) not null default 0 check (balance >= 0),
  updated_at  timestamptz not null default now()
);

create table wallet_transactions (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  type        wallet_txn_type not null,
  amount      numeric(12,2) not null,          -- signed: credits positive, debits negative
  currency    currency_code not null,
  balance_after numeric(12,2) not null,
  booking_id  uuid references bookings(id) on delete set null,
  gift_card_id uuid references gift_cards(id) on delete set null,
  note        text,
  created_at  timestamptz not null default now()
);
create index wallet_txn_profile_idx on wallet_transactions (profile_id, created_at desc);

create table invoices (
  id            uuid primary key default gen_random_uuid(),
  booking_id    uuid not null references bookings(id) on delete cascade,
  number        text not null unique,          -- INV-2026-000123, gapless per year
  issued_to     jsonb not null,                -- name, address, TRN
  currency      currency_code not null,
  subtotal      numeric(12,2) not null,
  tax_total     numeric(12,2) not null,
  total         numeric(12,2) not null,
  tax_lines     jsonb not null default '[]'::jsonb,  -- [{label:"VAT 5%", rate:5, amount:...}]
  pdf_url       text,
  issued_at     timestamptz not null default now()
);

create table payouts (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references companies(id) on delete restrict,
  period_start  date not null,
  period_end    date not null,
  currency      currency_code not null,
  gross_amount  numeric(12,2) not null,
  commission    numeric(12,2) not null,
  adjustments   numeric(12,2) not null default 0,
  net_amount    numeric(12,2) not null,
  status        payout_status not null default 'scheduled',
  provider_transfer_id text,
  paid_at       timestamptz,
  created_at    timestamptz not null default now(),
  unique (company_id, period_start, period_end)
);

create table payout_items (
  payout_id  uuid not null references payouts(id) on delete cascade,
  booking_id uuid not null references bookings(id) on delete restrict,
  amount     numeric(12,2) not null,
  primary key (payout_id, booking_id)
);

create trigger touch_bookings before update on bookings for each row execute function internal.touch_updated_at();
create trigger touch_payments before update on payments for each row execute function internal.touch_updated_at();
create trigger touch_wallets  before update on wallets  for each row execute function internal.touch_updated_at();

-- ---------- 0005_engagement_content_ads.sql ----------
-- =====================================================================
-- 0005_engagement_content_ads.sql
-- Reviews, traveler engagement, CMS, blog, monetization and audit trail.
-- =====================================================================

-- ---------------------------------------------------------------------
-- REVIEWS — only bookings that happened can be reviewed (verified badge).
-- ---------------------------------------------------------------------
create table reviews (
  id            uuid primary key default gen_random_uuid(),
  tour_id       uuid not null references tours(id) on delete cascade,
  company_id    uuid not null references companies(id) on delete cascade,
  profile_id    uuid references profiles(id) on delete set null,
  booking_item_id uuid references booking_items(id) on delete set null,
  status        review_status not null default 'pending',
  rating        smallint not null check (rating between 1 and 5),
  rating_value  smallint check (rating_value between 1 and 5),
  rating_guide  smallint check (rating_guide between 1 and 5),
  rating_safety smallint check (rating_safety between 1 and 5),
  title         text,
  body          text,
  locale        locale_code not null default 'en',
  traveler_type text check (traveler_type in ('solo','couple','family','friends','business')),
  travelled_on  date,
  helpful_count integer not null default 0,
  supplier_reply text,
  supplier_replied_at timestamptz,
  moderated_by  uuid references profiles(id) on delete set null,
  moderation_note text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create unique index reviews_one_per_item_uq on reviews (booking_item_id) where booking_item_id is not null;
create index reviews_tour_idx on reviews (tour_id, created_at desc) where status = 'published';
create index reviews_rating_idx on reviews (tour_id, rating) where status = 'published';

create table review_media (
  review_id uuid not null references reviews(id) on delete cascade,
  media_id  uuid not null references media_assets(id) on delete cascade,
  position  smallint not null default 0,
  primary key (review_id, media_id)
);

create table review_votes (
  review_id  uuid not null references reviews(id) on delete cascade,
  profile_id uuid not null references profiles(id) on delete cascade,
  is_helpful boolean not null,
  created_at timestamptz not null default now(),
  primary key (review_id, profile_id)
);

-- AI-generated digest of a tour's reviews; regenerated when count crosses a threshold.
create table review_summaries (
  tour_id       uuid not null references tours(id) on delete cascade,
  locale        locale_code not null,
  summary       text not null,
  pros          text[] not null default '{}',
  cons          text[] not null default '{}',
  source_count  integer not null,
  model         text not null,
  generated_at  timestamptz not null default now(),
  primary key (tour_id, locale)
);

-- ---------------------------------------------------------------------
-- TRAVELER ENGAGEMENT
-- ---------------------------------------------------------------------
create table wishlists (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  name        text not null default 'My wishlist',
  is_public   boolean not null default false,
  share_slug  text unique,
  created_at  timestamptz not null default now()
);

create table wishlist_items (
  wishlist_id uuid not null references wishlists(id) on delete cascade,
  tour_id     uuid not null references tours(id) on delete cascade,
  note        text,
  created_at  timestamptz not null default now(),
  primary key (wishlist_id, tour_id)
);

create table saved_searches (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  label       text not null,
  query       jsonb not null,           -- serialised filter state
  alert_freq  text not null default 'none' check (alert_freq in ('none','daily','weekly')),
  last_alerted_at timestamptz,
  created_at  timestamptz not null default now()
);

create table recently_viewed (
  profile_id uuid not null references profiles(id) on delete cascade,
  tour_id    uuid not null references tours(id) on delete cascade,
  viewed_at  timestamptz not null default now(),
  primary key (profile_id, tour_id)
);

create table notifications (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  channel     text not null default 'in_app' check (channel in ('in_app','email','push','sms','whatsapp')),
  topic       text not null,
  title       text not null,
  body        text,
  action_url  text,
  payload     jsonb not null default '{}'::jsonb,
  read_at     timestamptz,
  sent_at     timestamptz,
  created_at  timestamptz not null default now()
);
create index notifications_unread_idx on notifications (profile_id, created_at desc) where read_at is null;

-- ---------------------------------------------------------------------
-- CMS — every surface editable without a deploy.
-- ---------------------------------------------------------------------
create table cms_pages (
  id           uuid primary key default gen_random_uuid(),
  key          text not null unique,      -- 'home', 'about', 'partner-landing'
  template     text not null default 'flexible',
  status       content_status not null default 'draft',
  published_at timestamptz,
  updated_by   uuid references profiles(id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table cms_page_translations (
  page_id          uuid not null references cms_pages(id) on delete cascade,
  locale           locale_code not null,
  title            text not null,
  slug             text not null,
  meta_title       text,
  meta_description text,
  og_image_url     text,
  primary key (page_id, locale)
);
create unique index cms_page_slug_uq on cms_page_translations (locale, slug);

create table cms_blocks (
  id         uuid primary key default gen_random_uuid(),
  page_id    uuid not null references cms_pages(id) on delete cascade,
  position   smallint not null,
  block_type text not null,               -- 'hero', 'tour_rail', 'city_grid', 'faq', 'ad_slot'
  settings   jsonb not null default '{}'::jsonb,
  content    jsonb not null default '{}'::jsonb,   -- keyed by locale
  is_visible boolean not null default true,
  unique (page_id, position)
);

create table navigation_menus (
  id       uuid primary key default gen_random_uuid(),
  key      text not null unique,          -- 'header_main', 'footer_col_1'
  is_active boolean not null default true
);

create table navigation_items (
  id         uuid primary key default gen_random_uuid(),
  menu_id    uuid not null references navigation_menus(id) on delete cascade,
  parent_id  uuid references navigation_items(id) on delete cascade,
  position   smallint not null default 0,
  href       text not null,
  labels     jsonb not null default '{}'::jsonb,  -- {"en":"Things to do","ar":"..."}
  icon       text,
  badge      text,
  rel        text,
  is_visible boolean not null default true
);

create table site_settings (
  key         text primary key,
  value       jsonb not null,
  description text,
  updated_by  uuid references profiles(id) on delete set null,
  updated_at  timestamptz not null default now()
);

-- Third-party scripts and pixels, injected by placement with consent gating.
create table tracking_scripts (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  placement   text not null check (placement in ('head','body_start','body_end')),
  consent_category text not null default 'analytics' check (consent_category in ('necessary','analytics','marketing')),
  script      text not null,
  countries   char(2)[] not null default '{}',
  is_active   boolean not null default false,
  created_at  timestamptz not null default now()
);

create table redirects (
  id          uuid primary key default gen_random_uuid(),
  from_path   text not null unique,
  to_path     text not null,
  status_code smallint not null default 301 check (status_code in (301,302,307,308)),
  hits        integer not null default 0,
  created_at  timestamptz not null default now()
);

-- Per-URL SEO overrides for any entity, editable by the SEO team.
create table seo_overrides (
  id               uuid primary key default gen_random_uuid(),
  entity_type      text not null check (entity_type in ('tour','city','country','category','page','post','company')),
  entity_id        uuid not null,
  locale           locale_code not null,
  meta_title       text,
  meta_description text,
  canonical_url    text,
  robots           text,                 -- 'index,follow' | 'noindex,follow'
  og_image_url     text,
  faq_jsonld       jsonb,
  updated_by       uuid references profiles(id) on delete set null,
  updated_at       timestamptz not null default now(),
  unique (entity_type, entity_id, locale)
);

-- ---------------------------------------------------------------------
-- BLOG / TRAVEL MAGAZINE
-- ---------------------------------------------------------------------
create table blog_posts (
  id            uuid primary key default gen_random_uuid(),
  author_id     uuid not null references authors(id) on delete restrict,
  reviewer_id   uuid references authors(id) on delete set null,   -- EEAT: reviewed by
  status        content_status not null default 'draft',
  post_type     text not null default 'guide' check (post_type in ('guide','listicle','news','itinerary','food','culture','visa','event','review')),
  city_id       uuid references cities(id) on delete set null,
  country_id    uuid references countries(id) on delete set null,
  category_id   uuid references categories(id) on delete set null,
  cover_media_id uuid references media_assets(id) on delete set null,
  reading_minutes smallint,
  view_count    integer not null default 0,
  published_at  timestamptz,
  updated_at    timestamptz not null default now(),
  created_at    timestamptz not null default now()
);
create index blog_posts_published_idx on blog_posts (published_at desc) where status = 'published';

create table blog_post_translations (
  post_id          uuid not null references blog_posts(id) on delete cascade,
  locale           locale_code not null,
  title            text not null,
  slug             text not null,
  excerpt          text,
  body_mdx         text not null,
  meta_title       text,
  meta_description text,
  primary key (post_id, locale)
);
create unique index blog_slug_uq on blog_post_translations (locale, slug);

create table tags (
  id     uuid primary key default gen_random_uuid(),
  slug   text not null unique,
  labels jsonb not null default '{}'::jsonb
);

create table blog_post_tags (
  post_id uuid not null references blog_posts(id) on delete cascade,
  tag_id  uuid not null references tags(id) on delete cascade,
  primary key (post_id, tag_id)
);

create table blog_post_tours (
  post_id  uuid not null references blog_posts(id) on delete cascade,
  tour_id  uuid not null references tours(id) on delete cascade,
  position smallint not null default 0,
  primary key (post_id, tour_id)
);

-- ---------------------------------------------------------------------
-- MONETIZATION — house ad server, featured slots, memberships.
-- ---------------------------------------------------------------------
create table ad_campaigns (
  id            uuid primary key default gen_random_uuid(),
  advertiser_company_id uuid references companies(id) on delete cascade,
  advertiser_name text not null,
  pricing_model ad_pricing_model not null default 'cpm',
  rate          numeric(12,2) not null,
  currency      currency_code not null default 'AED',
  budget_total  numeric(12,2),
  budget_spent  numeric(12,2) not null default 0,
  starts_at     timestamptz not null,
  ends_at       timestamptz not null,
  is_active     boolean not null default false,
  created_at    timestamptz not null default now(),
  constraint campaign_window check (ends_at > starts_at)
);

create table ad_creatives (
  id           uuid primary key default gen_random_uuid(),
  campaign_id  uuid not null references ad_campaigns(id) on delete cascade,
  placement    ad_placement not null,
  format       text not null check (format in ('banner','native','video','popup','interstitial')),
  media_id     uuid references media_assets(id) on delete set null,
  headline     jsonb not null default '{}'::jsonb,
  body         jsonb not null default '{}'::jsonb,
  cta_label    jsonb not null default '{}'::jsonb,
  target_url   text not null,
  weight       smallint not null default 1,
  -- Targeting
  target_countries char(2)[] not null default '{}',
  target_city_ids  uuid[] not null default '{}',
  target_category_ids uuid[] not null default '{}',
  target_locales   locale_code[] not null default '{}',
  target_devices   text[] not null default '{}',
  frequency_cap_per_day smallint,
  is_active    boolean not null default true
);
create index ad_creatives_serving_idx on ad_creatives (placement) where is_active;

-- Impressions land in a partitioned table: high write volume, cheap pruning.
create table ad_impressions (
  id          bigint generated always as identity,
  creative_id uuid not null references ad_creatives(id) on delete cascade,
  occurred_at timestamptz not null default now(),
  session_id  text,
  country     char(2),
  city_id     uuid,
  device      text,
  locale      locale_code,
  is_click    boolean not null default false,
  revenue     numeric(12,4) not null default 0,
  primary key (id, occurred_at)
) partition by range (occurred_at);

create table ad_impressions_2026m08 partition of ad_impressions
  for values from ('2026-08-01') to ('2026-09-01');
create table ad_impressions_2026m09 partition of ad_impressions
  for values from ('2026-09-01') to ('2026-10-01');

create table featured_listings (
  id          uuid primary key default gen_random_uuid(),
  tour_id     uuid references tours(id) on delete cascade,
  company_id  uuid references companies(id) on delete cascade,
  slot        feature_slot not null,
  city_id     uuid references cities(id) on delete cascade,
  country_id  uuid references countries(id) on delete cascade,
  category_id uuid references categories(id) on delete cascade,
  position    smallint not null default 0,
  starts_at   timestamptz not null,
  ends_at     timestamptz not null,
  price_paid  numeric(12,2) not null default 0,
  currency    currency_code not null default 'AED',
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  constraint featured_target check (tour_id is not null or company_id is not null),
  constraint featured_window check (ends_at > starts_at)
);
create index featured_serving_idx on featured_listings (slot, starts_at, ends_at) where is_active;

create table memberships (
  id           uuid primary key default gen_random_uuid(),
  company_id   uuid not null references companies(id) on delete cascade,
  plan         text not null check (plan in ('free','growth','pro','enterprise')),
  status       text not null default 'active' check (status in ('trialing','active','past_due','cancelled')),
  price        numeric(12,2) not null default 0,
  currency     currency_code not null default 'AED',
  interval     text not null default 'month' check (interval in ('month','year')),
  benefits     jsonb not null default '{}'::jsonb,
  provider_subscription_id text,
  current_period_end timestamptz,
  created_at   timestamptz not null default now()
);
create unique index memberships_active_uq on memberships (company_id) where status in ('trialing','active');

create table affiliate_partners (
  id           uuid primary key default gen_random_uuid(),
  slug         text not null unique,
  name         text not null,
  vertical     text not null check (vertical in ('hotels','flights','insurance','visa','transfers','car_rental','esim')),
  base_url     text not null,
  param_map    jsonb not null default '{}'::jsonb,
  commission_note text,
  is_active    boolean not null default true
);

-- ---------------------------------------------------------------------
-- OBSERVABILITY
-- ---------------------------------------------------------------------
create table audit_logs (
  id          bigint generated always as identity primary key,
  actor_id    uuid references profiles(id) on delete set null,
  actor_role  user_role,
  action      text not null,               -- 'tour.publish', 'booking.refund'
  entity_type text not null,
  entity_id   uuid,
  before      jsonb,
  after       jsonb,
  ip          inet,
  user_agent  text,
  created_at  timestamptz not null default now()
);
create index audit_entity_idx on audit_logs (entity_type, entity_id, created_at desc);

create table search_queries (
  id          bigint generated always as identity primary key,
  query       text not null,
  locale      locale_code not null default 'en',
  city_id     uuid references cities(id) on delete set null,
  results_count integer not null default 0,
  clicked_tour_id uuid references tours(id) on delete set null,
  session_id  text,
  created_at  timestamptz not null default now()
);
create index search_queries_trgm_idx on search_queries using gin (query gin_trgm_ops);

create trigger touch_reviews before update on reviews for each row execute function internal.touch_updated_at();
create trigger touch_cms_pages before update on cms_pages for each row execute function internal.touch_updated_at();

-- ---------- 0006_search_and_functions.sql ----------
-- =====================================================================
-- 0006_search_and_functions.sql
-- Search index, price resolution, and the transactional booking core.
-- =====================================================================

-- ---------------------------------------------------------------------
-- SEARCH INDEX
-- One flattened row per (tour, locale). Trigram for autocomplete,
-- tsvector for relevance, plus the facets the listing page filters on.
-- ---------------------------------------------------------------------
create table tour_search_index (
  tour_id        uuid not null references tours(id) on delete cascade,
  locale         locale_code not null,
  title          text not null,
  slug           text not null,
  summary        text,
  city_id        uuid not null,
  city_name      text not null,
  country_id     uuid not null,
  country_name   text not null,
  company_id     uuid not null,
  company_name   text not null,
  category_ids   uuid[] not null default '{}',
  category_names text[] not null default '{}',
  tour_type      tour_type not null,
  confirmation   confirmation_type not null,
  day_parts      day_part[] not null default '{}',
  guide_locales  locale_code[] not null default '{}',
  duration_minutes integer not null,
  from_price     numeric(12,2) not null,
  currency       currency_code not null,
  discount_pct   smallint not null default 0,
  rating_avg     numeric(3,2) not null default 0,
  rating_count   integer not null default 0,
  popularity_score numeric(10,4) not null default 0,
  pickup_included boolean not null default false,
  family_friendly boolean not null default true,
  is_luxury      boolean not null default false,
  is_private     boolean not null default false,
  location       geography(point, 4326),
  document       tsvector,
  updated_at     timestamptz not null default now(),
  primary key (tour_id, locale)
);
create index tsi_document_gin on tour_search_index using gin (document);
create index tsi_title_trgm on tour_search_index using gin (title gin_trgm_ops);
create index tsi_facets_idx on tour_search_index (locale, city_id, from_price);
create index tsi_category_gin on tour_search_index using gin (category_ids);
create index tsi_location_gix on tour_search_index using gist (location);

-- Rebuild the index rows for a single tour. Called by triggers and by the
-- nightly reconciliation job, so it must be idempotent.
create or replace function internal.reindex_tour(p_tour_id uuid)
returns void
language plpgsql
security definer set search_path = public, internal
as $$
begin
  delete from tour_search_index where tour_id = p_tour_id;

  insert into tour_search_index (
    tour_id, locale, title, slug, summary, city_id, city_name, country_id, country_name,
    company_id, company_name, category_ids, category_names, tour_type, confirmation,
    day_parts, guide_locales, duration_minutes, from_price, currency, discount_pct,
    rating_avg, rating_count, popularity_score, pickup_included, family_friendly,
    is_luxury, is_private, location, document
  )
  select
    t.id,
    tt.locale,
    tt.title,
    tt.slug,
    tt.summary,
    t.city_id, ct.name,
    c.id, cot.name,
    t.company_id, comp.display_name,
    coalesce(cats.ids, '{}'::uuid[]),
    coalesce(cats.names, '{}'::text[]),
    t.tour_type, t.confirmation, t.day_parts, t.guide_locales,
    t.duration_minutes, t.from_price, t.base_currency, t.discount_pct,
    t.rating_avg, t.rating_count, t.popularity_score,
    t.pickup_included, t.family_friendly, t.is_luxury, t.is_private,
    coalesce(t.meeting_point, ci.centroid),
    setweight(to_tsvector('simple', coalesce(tt.title, '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(ct.name, '') || ' ' || coalesce(cot.name, '')), 'B') ||
    setweight(to_tsvector('simple', array_to_string(coalesce(cats.names, '{}'::text[]), ' ')), 'B') ||
    setweight(to_tsvector('simple', coalesce(tt.summary, '')), 'C') ||
    setweight(to_tsvector('simple', array_to_string(tt.highlights, ' ')), 'D')
  from tours t
  join tour_translations tt on tt.tour_id = t.id
  join cities ci on ci.id = t.city_id
  join city_translations ct on ct.city_id = ci.id and ct.locale = tt.locale
  join countries c on c.id = ci.country_id
  join country_translations cot on cot.country_id = c.id and cot.locale = tt.locale
  join companies comp on comp.id = t.company_id
  left join lateral (
    select array_agg(cat.id) as ids, array_agg(catt.name) as names
    from tour_categories tc
    join categories cat on cat.id = tc.category_id
    join category_translations catt on catt.category_id = cat.id and catt.locale = tt.locale
    where tc.tour_id = t.id
  ) cats on true
  where t.id = p_tour_id and t.status = 'published';
end;
$$;

-- Two trigger functions, because a `tours` record exposes `id` while every
-- child table exposes `tour_id`. One shared function would fail at runtime
-- on the missing field. Both are definer: a supplier inserting a tour has no
-- usage on the `internal` schema, by design.
create or replace function internal.reindex_from_tour()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  perform internal.reindex_tour(coalesce(new.id, old.id));
  return null;
end;
$$;

create or replace function internal.reindex_from_child()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  perform internal.reindex_tour(coalesce(new.tour_id, old.tour_id));
  return null;
end;
$$;

create trigger reindex_on_tour after insert or update on tours
  for each row execute function internal.reindex_from_tour();
create trigger reindex_on_translation after insert or update or delete on tour_translations
  for each row execute function internal.reindex_from_child();
create trigger reindex_on_category after insert or delete on tour_categories
  for each row execute function internal.reindex_from_child();

-- ---------------------------------------------------------------------
-- PRICING
-- Resolve the price for one pax type on one date: base price, then the
-- highest-priority matching rule wins. Pure and side-effect free.
-- ---------------------------------------------------------------------
create or replace function resolve_price(
  p_option_id uuid,
  p_pax       pax_type,
  p_date      date,
  p_currency  currency_code default 'AED'
)
returns table (list_price numeric, net_price numeric)
language plpgsql
stable
as $$
declare
  v_list numeric(12,2);
  v_net  numeric(12,2);
  v_rule price_rules%rowtype;
begin
  select tp.list_price, tp.net_price into v_list, v_net
  from tour_prices tp
  where tp.option_id = p_option_id and tp.pax = p_pax and tp.currency = p_currency;

  if v_list is null then
    return;   -- caller treats an empty result as "pax type not sold"
  end if;

  select * into v_rule
  from price_rules pr
  where pr.option_id = p_option_id
    and pr.is_active
    and (pr.pax is null or pr.pax = p_pax)
    and pr.valid_range @> p_date
    and extract(dow from p_date)::smallint = any (pr.weekdays)
  order by pr.priority desc, pr.id
  limit 1;

  if found then
    if v_rule.adjust_type = 'percentage' then
      v_list := round(v_list * (1 - v_rule.adjust_value / 100), 2);
    elsif v_rule.adjust_type = 'fixed_amount' then
      v_list := greatest(0, v_list - v_rule.adjust_value);
    end if;
  end if;

  return query select v_list, v_net;
end;
$$;

-- ---------------------------------------------------------------------
-- INVENTORY HOLDS
-- Seats are held (not booked) while the traveler pays. A hold takes a row
-- lock on the departure, so two concurrent checkouts cannot oversell.
-- ---------------------------------------------------------------------
create or replace function hold_seats(p_departure_id uuid, p_seats integer)
returns boolean
language plpgsql
security definer set search_path = public
as $$
declare
  v_free integer;
begin
  select capacity - seats_booked - seats_held into v_free
  from tour_departures
  where id = p_departure_id and not is_closed
  for update;

  if not found or v_free < p_seats then
    return false;
  end if;

  update tour_departures
     set seats_held = seats_held + p_seats
   where id = p_departure_id;

  return true;
end;
$$;

create or replace function release_seats(p_departure_id uuid, p_seats integer, p_convert boolean default false)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  update tour_departures
     set seats_held   = greatest(0, seats_held - p_seats),
         seats_booked = seats_booked + case when p_convert then p_seats else 0 end
   where id = p_departure_id;
end;
$$;

-- Reaper for abandoned checkouts. Scheduled every minute via pg_cron.
create or replace function expire_stale_holds()
returns integer
language plpgsql
security definer set search_path = public
as $$
declare
  v_count integer := 0;
  r record;
begin
  for r in
    select b.id from bookings b
    where b.status in ('pending','awaiting_payment')
      and b.hold_expires_at is not null
      and b.hold_expires_at < now()
    for update skip locked
  loop
    perform release_seats(bi.departure_id, bi.seats, false)
    from booking_items bi where bi.booking_id = r.id;

    update bookings set status = 'expired', hold_expires_at = null where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- BOOKING REFERENCE — human-readable, unambiguous (no O/0/I/1).
-- ---------------------------------------------------------------------
create or replace function internal.generate_booking_reference()
returns text
language plpgsql
as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_ref text;
  i integer;
begin
  loop
    v_ref := 'THG-';
    for i in 1..8 loop
      v_ref := v_ref || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from bookings where reference = v_ref);
  end loop;
  return v_ref;
end;
$$;

create or replace function internal.set_booking_reference()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  if new.reference is null or new.reference = '' then
    new.reference := internal.generate_booking_reference();
  end if;
  return new;
end;
$$;

create trigger booking_reference before insert on bookings
  for each row execute function internal.set_booking_reference();

-- ---------------------------------------------------------------------
-- CONFIRMATION — flips holds to booked and stamps tickets, atomically.
-- ---------------------------------------------------------------------
create or replace function confirm_booking(p_booking_id uuid)
returns bookings
language plpgsql
security definer set search_path = public
as $$
declare
  v_booking bookings;
  r record;
begin
  select * into v_booking from bookings where id = p_booking_id for update;
  if not found then
    raise exception 'Booking % not found', p_booking_id using errcode = 'no_data_found';
  end if;
  if v_booking.status = 'confirmed' then
    return v_booking;   -- idempotent: webhooks retry
  end if;
  if v_booking.status not in ('pending','awaiting_payment','on_hold') then
    raise exception 'Booking % cannot be confirmed from status %', p_booking_id, v_booking.status
      using errcode = 'invalid_parameter_value';
  end if;

  for r in select id, departure_id, seats from booking_items where booking_id = p_booking_id loop
    perform release_seats(r.departure_id, r.seats, true);
    update booking_items
       set ticket_code = encode(gen_random_bytes(16), 'hex')
     where id = r.id and ticket_code is null;
  end loop;

  update bookings
     set status = 'confirmed',
         confirmed_at = now(),
         hold_expires_at = null
   where id = p_booking_id
  returning * into v_booking;

  update tours t
     set booking_count = t.booking_count + 1
   from booking_items bi
   where bi.booking_id = p_booking_id and t.id = bi.tour_id;

  -- Coupon redemption is recorded here, inside the same transaction. Doing it
  -- in a follow-up call means a crash between the two leaves a coupon that was
  -- spent but never counted, and the usage limit stops meaning anything.
  if v_booking.coupon_id is not null then
    insert into coupon_redemptions (coupon_id, booking_id, profile_id, amount)
    values (v_booking.coupon_id, v_booking.id, v_booking.profile_id, v_booking.discount_total)
    on conflict (coupon_id, booking_id) do nothing;

    update coupons
       set used_count = used_count + 1
     where id = v_booking.coupon_id;
  end if;

  return v_booking;
end;
$$;

-- ---------------------------------------------------------------------
-- DERIVED AGGREGATES — ratings and popularity, kept in the write path
-- for ratings (users notice the lag) and batched for popularity.
-- ---------------------------------------------------------------------
-- Definer because a traveller publishing a review must update aggregate
-- columns on `tours` and `companies`, which their RLS policies rightly forbid
-- them from writing directly.
create or replace function internal.recalc_tour_rating()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  v_tour uuid := coalesce(new.tour_id, old.tour_id);
begin
  update tours t set
    rating_avg = coalesce(agg.avg_rating, 0),
    rating_count = coalesce(agg.cnt, 0)
  from (
    select avg(rating)::numeric(3,2) as avg_rating, count(*) as cnt
    from reviews where tour_id = v_tour and status = 'published'
  ) agg
  where t.id = v_tour;

  update companies c set
    rating_avg = coalesce(agg.avg_rating, 0),
    rating_count = coalesce(agg.cnt, 0)
  from (
    select avg(rating)::numeric(3,2) as avg_rating, count(*) as cnt
    from reviews where company_id = coalesce(new.company_id, old.company_id) and status = 'published'
  ) agg
  where c.id = coalesce(new.company_id, old.company_id);

  return null;
end;
$$;

create trigger recalc_rating after insert or update or delete on reviews
  for each row execute function internal.recalc_tour_rating();

-- Popularity blends recent bookings, rating quality and freshness.
-- Run nightly: select refresh_popularity_scores();
create or replace function refresh_popularity_scores()
returns void
language sql
security definer set search_path = public
as $$
  update tours t set popularity_score = round(
      (coalesce((
        select count(*) from booking_items bi
        join bookings b on b.id = bi.booking_id
        where bi.tour_id = t.id
          and b.status in ('confirmed','completed')
          and b.created_at > now() - interval '30 days'
      ), 0) * 5.0)
    + (t.rating_avg * least(t.rating_count, 200) * 0.35)
    + (least(t.view_count, 50000) * 0.002)
    - (extract(epoch from now() - coalesce(t.published_at, t.created_at)) / 86400.0 * 0.15)
  , 4)
  where t.status = 'published';
$$;

-- ---------------------------------------------------------------------
-- NEARBY — powers "attractions near this tour" and "experiences near me".
-- ---------------------------------------------------------------------
create or replace function nearby_tours(
  p_lat double precision,
  p_lng double precision,
  p_radius_m integer default 20000,
  p_locale locale_code default 'en',
  p_limit integer default 24
)
returns table (tour_id uuid, title text, slug text, distance_m double precision, from_price numeric, rating_avg numeric)
language sql
stable
as $$
  select si.tour_id, si.title, si.slug,
         st_distance(si.location, st_point(p_lng, p_lat)::geography) as distance_m,
         si.from_price, si.rating_avg
  from tour_search_index si
  where si.locale = p_locale
    and si.location is not null
    and st_dwithin(si.location, st_point(p_lng, p_lat)::geography, p_radius_m)
  order by distance_m asc, si.popularity_score desc
  limit p_limit;
$$;

-- ---------- 0007_rls_policies.sql ----------
-- =====================================================================
-- 0007_rls_policies.sql
-- Row Level Security. The API key alone grants nothing; every read and
-- write is authorised against the caller's JWT.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Authorisation helpers. security definer + stable so the planner can
-- cache them per statement instead of per row.
-- ---------------------------------------------------------------------
create or replace function auth_role()
returns user_role
language sql
stable
security definer set search_path = public
as $$
  select role from profiles where id = auth.uid();
$$;

create or replace function is_staff()
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select coalesce(auth_role() in ('support','admin','super_admin','editor'), false);
$$;

create or replace function is_admin()
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select coalesce(auth_role() in ('admin','super_admin'), false);
$$;

create or replace function is_company_member(p_company_id uuid)
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1 from company_members cm
    where cm.company_id = p_company_id
      and cm.profile_id = auth.uid()
      and cm.accepted_at is not null
  );
$$;

-- ---------------------------------------------------------------------
-- Enable RLS everywhere. Anything not covered by a policy is denied.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'profiles','authors','companies','company_members',
    'countries','country_translations','cities','city_translations','areas','area_translations',
    'points_of_interest','poi_translations','categories','category_translations',
    'tours','tour_translations','tour_categories','tour_itinerary','tour_itinerary_translations',
    'tour_faqs','tour_faq_translations','media_assets','tour_media','tour_pickup_points',
    'tour_options','tour_option_translations','tour_prices','price_rules',
    'tour_schedules','tour_departures','tour_search_index',
    'bookings','booking_items','booking_travelers','payments','payment_events','refunds',
    'coupons','coupon_redemptions','gift_cards','wallets','wallet_transactions','invoices',
    'payouts','payout_items',
    'reviews','review_media','review_votes','review_summaries',
    'wishlists','wishlist_items','saved_searches','recently_viewed','notifications',
    'cms_pages','cms_page_translations','cms_blocks','navigation_menus','navigation_items',
    'site_settings','tracking_scripts','redirects','seo_overrides',
    'blog_posts','blog_post_translations','tags','blog_post_tags','blog_post_tours',
    'ad_campaigns','ad_creatives','featured_listings','memberships','affiliate_partners',
    'audit_logs','search_queries'
  ]
  loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- PUBLIC CATALOG — readable by anonymous visitors, written by staff.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'countries','country_translations','cities','city_translations','areas','area_translations',
    'points_of_interest','poi_translations','categories','category_translations',
    'tour_search_index','navigation_menus','navigation_items','tags','affiliate_partners','redirects'
  ]
  loop
    execute format($p$create policy "%1$s_public_read" on %1$I for select using (true)$p$, t);
    execute format($p$create policy "%1$s_staff_write" on %1$I for all
                      using (is_staff()) with check (is_staff())$p$, t);
  end loop;
end $$;

-- Tours: published rows are public; drafts belong to their company and staff.
create policy tours_public_read on tours for select
  using (status = 'published' or is_company_member(company_id) or is_staff());
create policy tours_company_write on tours for insert
  with check (is_company_member(company_id) or is_admin());
create policy tours_company_update on tours for update
  using (is_company_member(company_id) or is_staff())
  with check (is_company_member(company_id) or is_staff());
create policy tours_admin_delete on tours for delete using (is_admin());

-- Child tables inherit visibility from their parent tour.
do $$
declare t text;
begin
  foreach t in array array[
    'tour_translations','tour_categories','tour_itinerary','tour_faqs','tour_media',
    'tour_pickup_points','tour_options','tour_schedules','tour_departures'
  ]
  loop
    execute format($p$create policy "%1$s_read" on %1$I for select using (
        exists (select 1 from tours t where t.id = %1$I.tour_id
                and (t.status = 'published' or is_company_member(t.company_id) or is_staff())))$p$, t);
    execute format($p$create policy "%1$s_write" on %1$I for all using (
        exists (select 1 from tours t where t.id = %1$I.tour_id
                and (is_company_member(t.company_id) or is_staff())))
      with check (
        exists (select 1 from tours t where t.id = %1$I.tour_id
                and (is_company_member(t.company_id) or is_staff())))$p$, t);
  end loop;
end $$;

create policy tour_prices_read on tour_prices for select using (
  exists (select 1 from tour_options o join tours t on t.id = o.tour_id
          where o.id = tour_prices.option_id
            and (t.status = 'published' or is_company_member(t.company_id) or is_staff())));
create policy tour_prices_write on tour_prices for all using (
  exists (select 1 from tour_options o join tours t on t.id = o.tour_id
          where o.id = tour_prices.option_id and (is_company_member(t.company_id) or is_staff())))
  with check (
  exists (select 1 from tour_options o join tours t on t.id = o.tour_id
          where o.id = tour_prices.option_id and (is_company_member(t.company_id) or is_staff())));

create policy media_read on media_assets for select using (true);
create policy media_write on media_assets for insert with check (auth.uid() is not null);
create policy media_owner_update on media_assets for update
  using (uploaded_by = auth.uid() or is_staff());

-- ---------------------------------------------------------------------
-- IDENTITY
-- ---------------------------------------------------------------------
create policy profiles_self_read on profiles for select
  using (id = auth.uid() or is_staff());
create policy profiles_self_update on profiles for update
  using (id = auth.uid()) with check (id = auth.uid() and role = auth_role());
create policy profiles_admin_all on profiles for all using (is_admin()) with check (is_admin());

create policy authors_public_read on authors for select using (is_active or is_staff());
create policy authors_staff_write on authors for all using (is_staff()) with check (is_staff());

create policy companies_public_read on companies for select
  using (status = 'active' or is_company_member(id) or is_staff());
create policy companies_member_update on companies for update
  using (is_company_member(id) or is_admin())
  with check (is_company_member(id) or is_admin());
create policy companies_admin_write on companies for insert with check (auth.uid() is not null);

create policy company_members_read on company_members for select
  using (profile_id = auth.uid() or is_company_member(company_id) or is_staff());
create policy company_members_manage on company_members for all
  using (is_company_member(company_id) or is_admin())
  with check (is_company_member(company_id) or is_admin());

-- ---------------------------------------------------------------------
-- BOOKINGS — travelers see their own; suppliers see theirs; nobody else.
-- Guest bookings are read through a signed server-side lookup, never RLS.
-- ---------------------------------------------------------------------
create policy bookings_owner_read on bookings for select
  using (profile_id = auth.uid() or is_company_member(company_id) or is_staff());
create policy bookings_owner_update on bookings for update
  using (is_company_member(company_id) or is_staff())
  with check (is_company_member(company_id) or is_staff());

create policy booking_items_read on booking_items for select using (
  exists (select 1 from bookings b where b.id = booking_items.booking_id
          and (b.profile_id = auth.uid() or is_company_member(b.company_id) or is_staff())));
create policy booking_travelers_read on booking_travelers for select using (
  exists (select 1 from booking_items bi join bookings b on b.id = bi.booking_id
          where bi.id = booking_travelers.item_id
            and (b.profile_id = auth.uid() or is_company_member(b.company_id) or is_staff())));

create policy payments_read on payments for select using (
  exists (select 1 from bookings b where b.id = payments.booking_id
          and (b.profile_id = auth.uid() or is_company_member(b.company_id) or is_staff())));
create policy invoices_read on invoices for select using (
  exists (select 1 from bookings b where b.id = invoices.booking_id
          and (b.profile_id = auth.uid() or is_company_member(b.company_id) or is_staff())));
create policy refunds_read on refunds for select using (
  exists (select 1 from bookings b where b.id = refunds.booking_id
          and (b.profile_id = auth.uid() or is_company_member(b.company_id) or is_staff())));

-- Payment webhooks and booking writes run through the service role only.
create policy payment_events_admin on payment_events for all using (is_admin()) with check (is_admin());

create policy wallets_self on wallets for select using (profile_id = auth.uid() or is_staff());
create policy wallet_txn_self on wallet_transactions for select using (profile_id = auth.uid() or is_staff());
create policy gift_cards_owner on gift_cards for select
  using (purchased_by = auth.uid() or is_staff());

create policy payouts_company on payouts for select
  using (is_company_member(company_id) or is_staff());
create policy payout_items_company on payout_items for select using (
  exists (select 1 from payouts p where p.id = payout_items.payout_id
          and (is_company_member(p.company_id) or is_staff())));

create policy coupons_read on coupons for select
  using (is_active or is_company_member(company_id) or is_staff());
create policy coupons_write on coupons for all
  using (is_company_member(company_id) or is_admin())
  with check (is_company_member(company_id) or is_admin());
create policy coupon_redemptions_read on coupon_redemptions for select
  using (profile_id = auth.uid() or is_staff());

-- ---------------------------------------------------------------------
-- REVIEWS — public when published; authored only by the person who travelled.
-- ---------------------------------------------------------------------
create policy reviews_public_read on reviews for select
  using (status = 'published' or profile_id = auth.uid() or is_company_member(company_id) or is_staff());
create policy reviews_insert on reviews for insert with check (
  profile_id = auth.uid()
  and exists (
    select 1 from booking_items bi
    join bookings b on b.id = bi.booking_id
    where bi.id = reviews.booking_item_id
      and b.profile_id = auth.uid()
      and b.status in ('confirmed','completed')
      and bi.starts_at < now()
  ));
create policy reviews_author_update on reviews for update
  using (profile_id = auth.uid() and status <> 'published')
  with check (profile_id = auth.uid());
create policy reviews_staff_moderate on reviews for update using (is_staff()) with check (is_staff());

create policy review_media_read on review_media for select using (true);
create policy review_votes_self on review_votes for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy review_summaries_read on review_summaries for select using (true);

-- ---------------------------------------------------------------------
-- PERSONAL DATA — strictly owner-scoped.
-- ---------------------------------------------------------------------
create policy wishlists_owner on wishlists for all
  using (profile_id = auth.uid() or is_public) with check (profile_id = auth.uid());
create policy wishlist_items_owner on wishlist_items for all using (
  exists (select 1 from wishlists w where w.id = wishlist_items.wishlist_id
          and (w.profile_id = auth.uid() or w.is_public)))
  with check (exists (select 1 from wishlists w where w.id = wishlist_items.wishlist_id and w.profile_id = auth.uid()));
create policy saved_searches_owner on saved_searches for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy recently_viewed_owner on recently_viewed for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy notifications_owner on notifications for select using (profile_id = auth.uid());
create policy notifications_owner_update on notifications for update
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());

-- ---------------------------------------------------------------------
-- CONTENT & MONETIZATION
-- ---------------------------------------------------------------------
create policy cms_pages_read on cms_pages for select using (status = 'published' or is_staff());
create policy cms_pages_write on cms_pages for all using (is_staff()) with check (is_staff());
create policy cms_page_tr_read on cms_page_translations for select using (
  exists (select 1 from cms_pages p where p.id = cms_page_translations.page_id
          and (p.status = 'published' or is_staff())));
create policy cms_page_tr_write on cms_page_translations for all using (is_staff()) with check (is_staff());
create policy cms_blocks_read on cms_blocks for select using (
  is_visible and exists (select 1 from cms_pages p where p.id = cms_blocks.page_id
                         and (p.status = 'published' or is_staff())));
create policy cms_blocks_write on cms_blocks for all using (is_staff()) with check (is_staff());

create policy blog_read on blog_posts for select using (status = 'published' or is_staff());
create policy blog_write on blog_posts for all using (is_staff()) with check (is_staff());
create policy blog_tr_read on blog_post_translations for select using (
  exists (select 1 from blog_posts p where p.id = blog_post_translations.post_id
          and (p.status = 'published' or is_staff())));
create policy blog_tr_write on blog_post_translations for all using (is_staff()) with check (is_staff());
create policy blog_tags_read on blog_post_tags for select using (true);
create policy blog_tours_read on blog_post_tours for select using (true);

create policy seo_overrides_read on seo_overrides for select using (true);
create policy seo_overrides_write on seo_overrides for all using (is_staff()) with check (is_staff());
create policy site_settings_read on site_settings for select using (true);
create policy site_settings_write on site_settings for all using (is_admin()) with check (is_admin());
create policy tracking_read on tracking_scripts for select using (is_active or is_admin());
create policy tracking_write on tracking_scripts for all using (is_admin()) with check (is_admin());

create policy ad_campaigns_read on ad_campaigns for select
  using (is_active or is_company_member(advertiser_company_id) or is_staff());
create policy ad_campaigns_write on ad_campaigns for all using (is_admin()) with check (is_admin());
create policy ad_creatives_read on ad_creatives for select using (is_active or is_staff());
create policy ad_creatives_write on ad_creatives for all using (is_admin()) with check (is_admin());
create policy featured_read on featured_listings for select using (is_active or is_staff());
create policy featured_write on featured_listings for all using (is_admin()) with check (is_admin());
create policy memberships_read on memberships for select
  using (is_company_member(company_id) or is_staff());
create policy memberships_write on memberships for all using (is_admin()) with check (is_admin());

create policy audit_read on audit_logs for select using (is_admin());
create policy search_queries_insert on search_queries for insert with check (true);
create policy search_queries_read on search_queries for select using (is_staff());

-- ---------- 0008_supplier_applications.sql ----------
-- =====================================================================
-- 0008_supplier_applications.sql
--
-- Three actors use this platform:
--   traveler       — books, reviews, owns only their own data
--   company_owner  — applied, was approved, manages one company's listings
--   admin          — reviews applications, moderates, sees everything
--
-- The dangerous transition is traveler -> company_owner. This migration
-- makes that transition a single audited function that only an admin can
-- call, so it cannot happen by any other path.
-- =====================================================================

create type application_status as enum (
  'draft', 'submitted', 'under_review', 'needs_info', 'approved', 'rejected', 'withdrawn'
);

create table company_applications (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid references companies(id) on delete cascade,
  submitted_by      uuid not null references profiles(id) on delete cascade,
  status            application_status not null default 'draft',

  -- What the applicant tells us.
  legal_name        text not null,
  display_name      text not null,
  country_id        uuid not null references countries(id) on delete restrict,
  city_id           uuid references cities(id) on delete set null,
  contact_email     citext not null,
  contact_phone     text not null,
  whatsapp          text,
  website           text,
  about             text not null,
  years_operating   smallint check (years_operating >= 0),
  tour_count_estimate smallint,
  categories        uuid[] not null default '{}',

  -- What we verify. URLs point at a private storage bucket, never public.
  trade_license_no  text not null,
  trade_license_url text not null,
  tax_registration_no text,
  insurance_url     text,
  tourism_permit_url text,
  documents         jsonb not null default '[]'::jsonb,

  -- Review trail.
  reviewed_by       uuid references profiles(id) on delete set null,
  reviewed_at       timestamptz,
  review_notes      text,
  rejection_reason  text,
  info_requested    text,

  submitted_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- One live application per person. A rejected applicant can reapply, because
-- rejection is usually a missing document rather than a permanent no.
create unique index company_applications_one_open_uq
  on company_applications (submitted_by)
  where status in ('draft', 'submitted', 'under_review', 'needs_info');

create index company_applications_queue_idx
  on company_applications (status, submitted_at)
  where status in ('submitted', 'under_review', 'needs_info');

create trigger touch_company_applications before update on company_applications
  for each row execute function internal.touch_updated_at();

-- Every status change is recorded, including who and why. Regulators and
-- disputes both ask "who approved this operator", and the answer has to exist.
create table company_application_events (
  id             bigint generated always as identity primary key,
  application_id uuid not null references company_applications(id) on delete cascade,
  actor_id       uuid references profiles(id) on delete set null,
  from_status    application_status,
  to_status      application_status not null,
  note           text,
  created_at     timestamptz not null default now()
);
create index application_events_idx on company_application_events (application_id, created_at);

-- security definer on purpose: an audit trigger that runs with the caller's
-- privileges is an audit trigger the caller can break. This one writes the
-- event no matter who acted or what they are otherwise allowed to touch.
create or replace function internal.log_application_event()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
  if tg_op = 'INSERT' or old.status is distinct from new.status then
    insert into company_application_events (application_id, actor_id, from_status, to_status, note)
    values (new.id, auth.uid(),
            case when tg_op = 'INSERT' then null else old.status end,
            new.status,
            coalesce(new.review_notes, new.rejection_reason, new.info_requested));
  end if;
  return new;
end;
$$;

create trigger log_application_status
  after insert or update on company_applications
  for each row execute function internal.log_application_event();

-- ---------------------------------------------------------------------
-- SUBMISSION — the applicant's own action.
-- ---------------------------------------------------------------------
-- Every status transition on an application goes through a function, and the
-- RLS policy forbids applicants from writing `status` directly. That is why
-- this is definer rather than invoker: the `submitted_by = auth.uid()` clause
-- below is the ownership check, and it is the only way in.
create or replace function submit_company_application(p_application_id uuid)
returns company_applications
language plpgsql
security definer
set search_path = public
as $$
declare
  v_app company_applications;
begin
  select * into v_app from company_applications
  where id = p_application_id and submitted_by = auth.uid()
  for update;

  if not found then
    raise exception 'Application not found' using errcode = 'no_data_found';
  end if;
  if v_app.status not in ('draft', 'needs_info') then
    raise exception 'This application has already been submitted'
      using errcode = 'invalid_parameter_value';
  end if;
  if coalesce(trim(v_app.trade_license_no), '') = '' or coalesce(trim(v_app.trade_license_url), '') = '' then
    raise exception 'A trade licence number and document are required'
      using errcode = 'invalid_parameter_value';
  end if;

  update company_applications
     set status = 'submitted', submitted_at = now(), info_requested = null
   where id = p_application_id
  returning * into v_app;

  return v_app;
end;
$$;

-- ---------------------------------------------------------------------
-- APPROVAL — the privilege boundary.
--
-- security definer, because it must write to profiles.role, which the RLS
-- policy on profiles deliberately forbids everyone from doing. The first
-- statement re-checks that the caller is an admin: a definer function
-- without that check is a privilege-escalation hole with extra steps.
-- ---------------------------------------------------------------------
create or replace function approve_company_application(
  p_application_id uuid,
  p_commission_rate numeric default 20.00,
  p_note text default null
)
returns companies
language plpgsql
security definer
set search_path = public
as $$
declare
  v_app     company_applications;
  v_company companies;
  v_slug    text;
  v_suffix  integer := 0;
begin
  if not is_admin() then
    raise exception 'Only an administrator can approve an application'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_app from company_applications where id = p_application_id for update;
  if not found then
    raise exception 'Application not found' using errcode = 'no_data_found';
  end if;
  if v_app.status = 'approved' then
    return (select c from companies c where c.id = v_app.company_id);  -- idempotent
  end if;
  if v_app.status not in ('submitted', 'under_review', 'needs_info') then
    raise exception 'Cannot approve an application with status %', v_app.status
      using errcode = 'invalid_parameter_value';
  end if;

  -- Slugs are public URLs and permanent, so collisions are resolved once here
  -- rather than left for the operator to discover after their page is live.
  v_slug := internal.slugify(v_app.display_name);
  while exists (select 1 from companies where slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := internal.slugify(v_app.display_name) || '-' || v_suffix;
  end loop;

  insert into companies (
    slug, legal_name, display_name, status, verification, country_id, city_id,
    contact_email, contact_phone, whatsapp, website, about,
    trade_license_no, trade_license_url, tax_registration_no,
    commission_rate, payout_currency, onboarded_at
  )
  select v_slug, v_app.legal_name, v_app.display_name, 'active', 'verified',
         v_app.country_id, v_app.city_id, v_app.contact_email, v_app.contact_phone,
         v_app.whatsapp, v_app.website, v_app.about,
         v_app.trade_license_no, v_app.trade_license_url, v_app.tax_registration_no,
         p_commission_rate, c.currency, now()
  from countries c where c.id = v_app.country_id
  returning * into v_company;

  -- The applicant becomes the owner: membership row plus the role change.
  insert into company_members (company_id, profile_id, role, permissions, accepted_at)
  values (v_company.id, v_app.submitted_by, 'company_owner',
          array['tours.write','bookings.read','payouts.read','staff.write'], now());

  -- Never demote an existing admin who happens to also run a company.
  update profiles
     set role = 'company_owner'
   where id = v_app.submitted_by
     and role = 'traveler';

  update company_applications
     set status = 'approved', company_id = v_company.id,
         reviewed_by = auth.uid(), reviewed_at = now(), review_notes = p_note
   where id = p_application_id;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'company_application.approve', 'company', v_company.id,
          jsonb_build_object('application_id', p_application_id, 'slug', v_slug,
                             'commission_rate', p_commission_rate));

  return v_company;
end;
$$;

create or replace function reject_company_application(
  p_application_id uuid,
  p_reason text
)
returns company_applications
language plpgsql
security definer
set search_path = public
as $$
declare
  v_app company_applications;
begin
  if not is_admin() then
    raise exception 'Only an administrator can reject an application'
      using errcode = 'insufficient_privilege';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A rejection reason is required' using errcode = 'invalid_parameter_value';
  end if;

  update company_applications
     set status = 'rejected', rejection_reason = p_reason,
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_application_id
     and status in ('submitted', 'under_review', 'needs_info')
  returning * into v_app;

  if not found then
    raise exception 'Application not found or not open for review' using errcode = 'no_data_found';
  end if;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'company_application.reject', 'company_application',
          p_application_id, jsonb_build_object('reason', p_reason));

  return v_app;
end;
$$;

create or replace function request_application_info(
  p_application_id uuid,
  p_message text
)
returns company_applications
language plpgsql
security definer
set search_path = public
as $$
declare
  v_app company_applications;
begin
  if not is_staff() then
    raise exception 'Only staff can request more information'
      using errcode = 'insufficient_privilege';
  end if;

  update company_applications
     set status = 'needs_info', info_requested = p_message,
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_application_id and status in ('submitted', 'under_review')
  returning * into v_app;

  if not found then
    raise exception 'Application not found or not open for review' using errcode = 'no_data_found';
  end if;

  return v_app;
end;
$$;

-- Suspension is separate from rejection: it acts on a live operator and must
-- take their listings down in the same transaction, not in a follow-up job.
create or replace function suspend_company(p_company_id uuid, p_reason text)
returns companies
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company companies;
begin
  if not is_admin() then
    raise exception 'Only an administrator can suspend a company'
      using errcode = 'insufficient_privilege';
  end if;

  update tours set status = 'paused'
   where company_id = p_company_id and status = 'published';

  update companies
     set status = 'suspended', suspended_reason = p_reason
   where id = p_company_id
  returning * into v_company;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'company.suspend', 'company', p_company_id,
          jsonb_build_object('reason', p_reason));

  return v_company;
end;
$$;

-- ---------------------------------------------------------------------
-- RLS — applicants see only their own application; staff see the queue.
-- ---------------------------------------------------------------------
alter table company_applications enable row level security;
alter table company_applications force row level security;
alter table company_application_events enable row level security;
alter table company_application_events force row level security;

create policy applications_own_read on company_applications for select
  using (submitted_by = auth.uid() or is_staff());

create policy applications_own_insert on company_applications for insert
  with check (submitted_by = auth.uid());

-- An applicant may edit the content of a draft, or answer a request for
-- information. They may not move it between states: `status` stays pinned to
-- its current value, and submission goes through submit_company_application().
-- reviewer and company_id are likewise set only by the definer functions.
create policy applications_own_update on company_applications for update
  using (submitted_by = auth.uid() and status in ('draft', 'needs_info'))
  with check (
    submitted_by = auth.uid()
    and status in ('draft', 'needs_info')
    and reviewed_by is null
    and company_id is null
    and rejection_reason is null
  );

create policy applications_staff_update on company_applications for update
  using (is_staff()) with check (is_staff());

create policy application_events_read on company_application_events for select
  using (
    is_staff()
    or exists (
      select 1 from company_applications a
      where a.id = company_application_events.application_id
        and a.submitted_by = auth.uid()
    )
  );

-- ---------- 0009_search_index_media.sql ----------
-- =====================================================================
-- 0009_search_index_media.sql
--
-- Listing pages render a card per tour, and every card needs a cover image.
-- Without it in the index, a 24-result page becomes 24 extra queries. The
-- image columns are denormalised here and maintained by reindex_tour(),
-- which already runs on every publish and every edit.
-- =====================================================================

alter table tour_search_index
  add column cover_url      text,
  add column cover_alt      text,
  add column cover_blurhash text,
  add column cover_width    integer,
  add column cover_height   integer,
  add column cancellation   cancellation_policy,
  add column min_age        smallint;

-- Rebuilt to include the cover. Same signature, so every existing trigger
-- keeps working untouched.
create or replace function internal.reindex_tour(p_tour_id uuid)
returns void
language plpgsql
security definer set search_path = public, internal
as $$
begin
  delete from tour_search_index where tour_id = p_tour_id;

  insert into tour_search_index (
    tour_id, locale, title, slug, summary, city_id, city_name, country_id, country_name,
    company_id, company_name, category_ids, category_names, tour_type, confirmation,
    day_parts, guide_locales, duration_minutes, from_price, currency, discount_pct,
    rating_avg, rating_count, popularity_score, pickup_included, family_friendly,
    is_luxury, is_private, location, document,
    cover_url, cover_alt, cover_blurhash, cover_width, cover_height,
    cancellation, min_age
  )
  select
    t.id,
    tt.locale,
    tt.title,
    tt.slug,
    tt.summary,
    t.city_id, ct.name,
    c.id, cot.name,
    t.company_id, comp.display_name,
    coalesce(cats.ids, '{}'::uuid[]),
    coalesce(cats.names, '{}'::text[]),
    t.tour_type, t.confirmation, t.day_parts, t.guide_locales,
    t.duration_minutes, t.from_price, t.base_currency, t.discount_pct,
    t.rating_avg, t.rating_count, t.popularity_score,
    t.pickup_included, t.family_friendly, t.is_luxury, t.is_private,
    coalesce(t.meeting_point, ci.centroid),
    setweight(to_tsvector('simple', coalesce(tt.title, '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(ct.name, '') || ' ' || coalesce(cot.name, '')), 'B') ||
    setweight(to_tsvector('simple', array_to_string(coalesce(cats.names, '{}'::text[]), ' ')), 'B') ||
    setweight(to_tsvector('simple', coalesce(tt.summary, '')), 'C') ||
    setweight(to_tsvector('simple', array_to_string(tt.highlights, ' ')), 'D'),
    cover.url,
    -- Alt text falls back to a description built from real data. An empty alt
    -- on a listing grid is both an accessibility failure and lost image SEO.
    coalesce(cover.alt_text ->> tt.locale::text, tt.title || ' — ' || ct.name),
    cover.blurhash,
    cover.width,
    cover.height,
    t.cancellation,
    t.min_age
  from tours t
  join tour_translations tt on tt.tour_id = t.id
  join cities ci on ci.id = t.city_id
  join city_translations ct on ct.city_id = ci.id and ct.locale = tt.locale
  join countries c on c.id = ci.country_id
  join country_translations cot on cot.country_id = c.id and cot.locale = tt.locale
  join companies comp on comp.id = t.company_id
  left join lateral (
    select array_agg(cat.id) as ids, array_agg(catt.name) as names
    from tour_categories tc
    join categories cat on cat.id = tc.category_id
    join category_translations catt on catt.category_id = cat.id and catt.locale = tt.locale
    where tc.tour_id = t.id
  ) cats on true
  left join lateral (
    select ma.url, ma.blurhash, ma.width, ma.height, tm.alt_text
    from tour_media tm
    join media_assets ma on ma.id = tm.media_id
    where tm.tour_id = t.id
    order by tm.is_cover desc, tm.position
    limit 1
  ) cover on true
  where t.id = p_tour_id and t.status = 'published';
end;
$$;

-- A media change must refresh the index too, or a supplier swapping their
-- cover photo sees the old one on every listing page until the next edit.
create trigger reindex_on_media after insert or update or delete on tour_media
  for each row execute function internal.reindex_from_child();

-- Backfill anything already indexed.
do $$
declare r record;
begin
  for r in select distinct tour_id from tour_search_index loop
    perform internal.reindex_tour(r.tour_id);
  end loop;
end $$;

-- Sort orders the listing page offers. Each needs an index or the first
-- popular city makes every "sort by price" a sequential scan.
create index if not exists tsi_price_sort on tour_search_index (locale, city_id, from_price);
create index if not exists tsi_rating_sort on tour_search_index (locale, city_id, rating_avg desc);
create index if not exists tsi_discount_sort on tour_search_index (locale, city_id, discount_pct desc);
create index if not exists tsi_duration_idx on tour_search_index (locale, city_id, duration_minutes);

-- ---------- 0010_homepage_and_newsletter.sql ----------
-- =====================================================================
-- 0010_homepage_and_newsletter.sql
--
-- Supports a data-driven homepage: newsletter capture, popular search
-- suggestions, and a cached stats snapshot so the homepage never runs
-- count(*) across the catalogue on every request.
-- =====================================================================

create table newsletter_subscribers (
  id            uuid primary key default gen_random_uuid(),
  email         citext not null unique,
  locale        locale_code not null default 'en',
  country_id    uuid references countries(id) on delete set null,
  source        text not null default 'homepage',
  -- Double opt-in is not optional in most GCC markets, and a list built
  -- without it gets your sending domain blocked.
  confirmed_at  timestamptz,
  confirm_token text not null default encode(gen_random_bytes(24), 'hex'),
  unsubscribed_at timestamptz,
  created_at    timestamptz not null default now()
);
create index newsletter_pending_idx on newsletter_subscribers (created_at)
  where confirmed_at is null and unsubscribed_at is null;

-- Editorially curated search suggestions, shown under the hero. Seeded by
-- hand at launch, later informed by `search_queries`.
create table popular_searches (
  id         uuid primary key default gen_random_uuid(),
  locale     locale_code not null,
  label      text not null,
  href       text not null,
  position   smallint not null default 0,
  is_active  boolean not null default true,
  unique (locale, label)
);

-- Homepage counters. Recomputing these per request means several count(*)
-- scans on the hottest page on the site; refreshed by cron instead.
create materialized view homepage_stats as
select
  (select count(*) from tours where status = 'published')                    as tour_count,
  (select count(*) from companies where status = 'active')                   as operator_count,
  (select count(*) from cities where is_active)                              as city_count,
  (select count(*) from countries where is_launched)                         as country_count,
  (select count(*) from reviews where status = 'published')                  as review_count,
  (select coalesce(round(avg(rating), 2), 0) from reviews where status = 'published') as rating_avg,
  now()                                                                       as refreshed_at;

create unique index homepage_stats_uq on homepage_stats ((true));

-- Non-concurrent on purpose. REFRESH ... CONCURRENTLY cannot run inside a
-- function body, and this view is a single row of counts — the refresh takes
-- milliseconds, so the brief exclusive lock is cheaper than the complexity of
-- calling it outside a transaction. If the counts ever get slow, move the
-- CONCURRENTLY refresh into the cron route instead of this function.
create or replace function refresh_homepage_stats()
returns void
language sql
security definer set search_path = public
as $$
  refresh materialized view homepage_stats;
$$;

alter table newsletter_subscribers enable row level security;
alter table newsletter_subscribers force row level security;
alter table popular_searches enable row level security;
alter table popular_searches force row level security;

-- Anyone may subscribe; nobody may read the list except staff. A publicly
-- readable subscriber table is a harvestable email list.
create policy newsletter_insert on newsletter_subscribers for insert with check (true);
create policy newsletter_staff_read on newsletter_subscribers for select using (is_staff());
create policy newsletter_staff_write on newsletter_subscribers for update using (is_staff()) with check (is_staff());

create policy popular_searches_read on popular_searches for select using (is_active);
create policy popular_searches_write on popular_searches for all using (is_staff()) with check (is_staff());

grant select on homepage_stats to anon, authenticated;

-- ---------- 0011_tour_workflow_and_dashboard.sql ----------
-- =====================================================================
-- 0011_tour_workflow_and_dashboard.sql
--
-- Listing workflow and the supplier CRM's read models.
--
-- The important part is the first section: until now a company member could
-- update their own tour to status = 'published' directly, which made the
-- whole approval model decorative. Publishing is now a privileged action.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. PUBLISHING IS NOT A SUPPLIER ACTION
-- ---------------------------------------------------------------------
alter table tours
  add column submitted_at        timestamptz,
  add column submitted_by        uuid references profiles(id) on delete set null,
  add column reviewed_at         timestamptz,
  add column reviewed_by         uuid references profiles(id) on delete set null,
  add column review_notes        text,
  add column completeness_score  smallint not null default 0,
  add column last_edited_by      uuid references profiles(id) on delete set null;

/**
 * Guards the status column. A supplier may move a tour between draft,
 * in_review and paused. Only staff may move it to published or rejected.
 *
 * A trigger rather than an RLS policy because RLS's WITH CHECK cannot see the
 * OLD row, so it cannot express "you may change this column to these values
 * but only from those values".
 */
create or replace function internal.guard_tour_status()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  if new.status is distinct from old.status and not is_staff() then
    -- The only transition a supplier may not make is the one that puts a
    -- listing in front of travellers. Everything else — pulling it back to
    -- draft, pausing it, archiving it — is theirs to do at any time, and
    -- blocking that would mean they cannot stop selling a tour they can no
    -- longer run.
    if new.status not in ('draft', 'in_review', 'paused', 'archived') then
      raise exception 'Only the TravelHub team can publish a listing. Submit it for review instead.'
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  -- These are set by the workflow functions, never by a client update.
  if not is_staff() then
    new.reviewed_at := old.reviewed_at;
    new.reviewed_by := old.reviewed_by;
    new.review_notes := old.review_notes;
    new.published_at := old.published_at;
  end if;

  new.last_edited_by := coalesce(auth.uid(), old.last_edited_by);
  return new;
end;
$$;

create trigger guard_tour_status before update on tours
  for each row execute function internal.guard_tour_status();

-- ---------------------------------------------------------------------
-- 2. COMPLETENESS — what the dashboard nags about
-- ---------------------------------------------------------------------
create or replace function tour_completeness(p_tour_id uuid)
returns table (score smallint, missing text[])
language plpgsql
stable
as $$
declare
  v_missing text[] := '{}';
  v_total   int := 10;
  v_done    int := 0;
  r record;
begin
  select t.*,
    (select count(*) from tour_media m where m.tour_id = t.id)      as media_count,
    (select count(*) from tour_options o where o.tour_id = t.id)    as option_count,
    (select count(*) from tour_faqs f where f.tour_id = t.id)       as faq_count,
    (select count(*) from tour_itinerary i where i.tour_id = t.id)  as stop_count,
    (select count(*) from tour_departures d where d.tour_id = t.id
       and d.starts_at > now())                                     as future_departures,
    (select count(*) from tour_prices p
       join tour_options o2 on o2.id = p.option_id
       where o2.tour_id = t.id)                                     as price_count
  into r
  from tours t where t.id = p_tour_id;

  if r is null then
    return query select 0::smallint, array['Tour not found']::text[];
    return;
  end if;

  if exists (select 1 from tour_translations tt where tt.tour_id = p_tour_id
             and coalesce(length(tt.title), 0) >= 20)
    then v_done := v_done + 1; else v_missing := v_missing || 'A descriptive title of at least 20 characters'::text; end if;

  if exists (select 1 from tour_translations tt where tt.tour_id = p_tour_id
             and coalesce(length(tt.description), 0) >= 300)
    then v_done := v_done + 1; else v_missing := v_missing || 'A description of at least 300 characters'::text; end if;

  if exists (select 1 from tour_translations tt where tt.tour_id = p_tour_id
             and array_length(tt.highlights, 1) >= 3)
    then v_done := v_done + 1; else v_missing := v_missing || 'At least three highlights'::text; end if;

  if exists (select 1 from tour_translations tt where tt.tour_id = p_tour_id
             and array_length(tt.inclusions, 1) >= 1)
    then v_done := v_done + 1; else v_missing := v_missing || 'What is included in the price'::text; end if;

  -- Three photos is the point where a listing stops looking abandoned.
  if r.media_count >= 3 then v_done := v_done + 1;
    else v_missing := v_missing || 'At least three photos'::text; end if;

  if r.option_count >= 1 then v_done := v_done + 1;
    else v_missing := v_missing || 'At least one bookable option'::text; end if;

  if r.price_count >= 1 then v_done := v_done + 1;
    else v_missing := v_missing || 'A price for at least one traveller type'::text; end if;

  if r.future_departures >= 1 then v_done := v_done + 1;
    else v_missing := v_missing || 'Availability on at least one future date'::text; end if;

  if r.faq_count >= 2 then v_done := v_done + 1;
    else v_missing := v_missing || 'At least two FAQs (these win Google rich results)'::text; end if;

  if exists (select 1 from tour_translations tt where tt.tour_id = p_tour_id
             and coalesce(length(tt.meta_description), 0) between 70 and 165)
    then v_done := v_done + 1; else v_missing := v_missing || 'A meta description of 70–165 characters'::text; end if;

  return query select round((v_done::numeric / v_total) * 100)::smallint, v_missing;
end;
$$;

-- ---------------------------------------------------------------------
-- 3. WORKFLOW FUNCTIONS
-- ---------------------------------------------------------------------
create or replace function submit_tour_for_review(p_tour_id uuid)
returns tours
language plpgsql
security definer set search_path = public
as $$
declare
  v_tour tours;
  v_score smallint;
  v_missing text[];
begin
  select * into v_tour from tours where id = p_tour_id for update;
  if not found then
    raise exception 'Listing not found' using errcode = 'no_data_found';
  end if;
  if not (is_company_member(v_tour.company_id) or is_staff()) then
    raise exception 'You do not have access to that listing' using errcode = 'insufficient_privilege';
  end if;
  if v_tour.status not in ('draft', 'rejected', 'paused') then
    raise exception 'This listing is already % ', v_tour.status using errcode = 'invalid_parameter_value';
  end if;

  select score, missing into v_score, v_missing from tour_completeness(p_tour_id);

  -- Reject incomplete submissions here rather than wasting a reviewer's time
  -- and the supplier's turnaround on something obviously unfinished.
  if v_score < 80 then
    raise exception 'This listing is % complete. Still needed: %',
      v_score || '%', array_to_string(v_missing, '; ')
      using errcode = 'invalid_parameter_value';
  end if;

  update tours
     set status = 'in_review', submitted_at = now(), submitted_by = auth.uid(),
         completeness_score = v_score
   where id = p_tour_id
  returning * into v_tour;

  return v_tour;
end;
$$;

create or replace function approve_tour(p_tour_id uuid, p_note text default null)
returns tours
language plpgsql
security definer set search_path = public
as $$
declare v_tour tours;
begin
  if not is_staff() then
    raise exception 'Only the TravelHub team can publish a listing'
      using errcode = 'insufficient_privilege';
  end if;

  update tours
     set status = 'published', published_at = coalesce(published_at, now()),
         reviewed_at = now(), reviewed_by = auth.uid(), review_notes = p_note,
         rejected_reason = null
   where id = p_tour_id and status in ('in_review', 'paused', 'rejected')
  returning * into v_tour;

  if not found then
    raise exception 'Listing not found or not awaiting review' using errcode = 'no_data_found';
  end if;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'tour.approve', 'tour', p_tour_id,
          jsonb_build_object('note', p_note));

  return v_tour;
end;
$$;

create or replace function reject_tour(p_tour_id uuid, p_reason text)
returns tours
language plpgsql
security definer set search_path = public
as $$
declare v_tour tours;
begin
  if not is_staff() then
    raise exception 'Only the TravelHub team can reject a listing'
      using errcode = 'insufficient_privilege';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Tell the operator what needs fixing' using errcode = 'invalid_parameter_value';
  end if;

  update tours
     set status = 'rejected', rejected_reason = p_reason,
         reviewed_at = now(), reviewed_by = auth.uid()
   where id = p_tour_id and status = 'in_review'
  returning * into v_tour;

  if not found then
    raise exception 'Listing not found or not awaiting review' using errcode = 'no_data_found';
  end if;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'tour.reject', 'tour', p_tour_id,
          jsonb_build_object('reason', p_reason));

  return v_tour;
end;
$$;

-- ---------------------------------------------------------------------
-- 4. AVAILABILITY — bulk generation, the single most tedious supplier task
-- ---------------------------------------------------------------------
create or replace function generate_departures(
  p_option_id uuid,
  p_from      date,
  p_to        date,
  p_time      time,
  p_capacity  integer,
  p_weekdays  smallint[] default '{0,1,2,3,4,5,6}',
  p_timezone  text default 'Asia/Dubai'
)
returns integer
language plpgsql
security definer set search_path = public
as $$
declare
  v_tour_id uuid;
  v_company uuid;
  v_count   integer := 0;
begin
  select o.tour_id, t.company_id into v_tour_id, v_company
  from tour_options o join tours t on t.id = o.tour_id
  where o.id = p_option_id;

  if v_tour_id is null then
    raise exception 'Option not found' using errcode = 'no_data_found';
  end if;
  if not (is_company_member(v_company) or is_staff()) then
    raise exception 'You do not have access to that listing' using errcode = 'insufficient_privilege';
  end if;
  if p_to < p_from then
    raise exception 'End date must be after the start date' using errcode = 'invalid_parameter_value';
  end if;
  if p_to - p_from > 400 then
    raise exception 'Generate at most 400 days at a time' using errcode = 'invalid_parameter_value';
  end if;

  -- ON CONFLICT DO NOTHING means re-running over an existing range never
  -- resets seats_booked on dates that already have bookings.
  insert into tour_departures (tour_id, option_id, starts_at, local_date, capacity)
  select v_tour_id, p_option_id,
         (d::date + p_time) at time zone p_timezone,
         d::date, p_capacity
  from generate_series(p_from, p_to, interval '1 day') d
  where extract(dow from d)::smallint = any (p_weekdays)
  on conflict (option_id, starts_at) do nothing;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- 5. DASHBOARD READ MODELS
-- ---------------------------------------------------------------------
-- security_invoker is not optional here. A Postgres view runs with its
-- OWNER's privileges by default, so a view over an RLS-protected table hands
-- every row to every caller — a cross-tenant leak that the base table's
-- policies do nothing to stop. This was caught by 05_operations.sql, where a
-- rival operator could read another company's manifest.
create or replace view supplier_tour_rows
with (security_invoker = true) as
select
  t.id, t.company_id, t.status, t.city_id, t.updated_at, t.submitted_at,
  t.rejected_reason, t.review_notes, t.completeness_score,
  t.from_price, t.base_currency, t.rating_avg, t.rating_count, t.booking_count,
  tt.locale, tt.title, tt.slug, tt.meta_title, tt.meta_description,
  (select count(*) from tour_media m where m.tour_id = t.id)                     as media_count,
  (select count(*) from tour_departures d
     where d.tour_id = t.id and d.starts_at > now() and not d.is_closed)         as future_departures,
  (select coalesce(sum(d.capacity - d.seats_booked - d.seats_held), 0)
     from tour_departures d where d.tour_id = t.id and d.starts_at > now())      as seats_available
from tours t
join tour_translations tt on tt.tour_id = t.id;

-- Revenue and volume per company per day. A view rather than a materialized
-- one: suppliers need today's numbers, not last night's.
create or replace view supplier_daily_stats
with (security_invoker = true) as
select
  b.company_id,
  date_trunc('day', b.created_at)::date as day,
  b.currency,
  count(*)                                                          as bookings,
  sum(b.grand_total)                                                as gross,
  sum(b.commission_total)                                           as commission,
  sum(b.supplier_net)                                               as net,
  count(*) filter (where b.status in ('cancelled_by_user','cancelled_by_supplier')) as cancellations
from bookings b
where b.status in ('confirmed', 'completed', 'cancelled_by_user', 'cancelled_by_supplier')
group by b.company_id, date_trunc('day', b.created_at), b.currency;

grant select on supplier_tour_rows, supplier_daily_stats to anon, authenticated;

create index tours_review_queue_idx on tours (submitted_at)
  where status = 'in_review';

-- ---------- 0012_media_operations_payouts.sql ----------
-- =====================================================================
-- 0012_media_operations_payouts.sql
--
-- Photo upload, day-of-travel operations (manifests, ticket redemption),
-- review replies and payout statements.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. STORAGE
-- Two buckets with opposite rules. Tour photos are public because they
-- appear on public pages; verification documents are private because a
-- trade licence is a scan of someone's identity paperwork.
-- ---------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('tour-media', 'tour-media', true, 10485760,
   array['image/jpeg','image/png','image/webp','image/avif']),
  ('operator-documents', 'operator-documents', false, 20971520,
   array['image/jpeg','image/png','application/pdf'])
on conflict (id) do nothing;

-- Path convention: tour-media/{company_id}/{tour_id}/{filename}. The company
-- id being the first segment is what makes the policy below expressible.
create policy "tour media is publicly readable"
  on storage.objects for select
  using (bucket_id = 'tour-media');

create policy "operators upload to their own folder"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'tour-media'
    and is_company_member(((storage.foldername(name))[1])::uuid)
  );

create policy "operators replace their own media"
  on storage.objects for update to authenticated
  using (bucket_id = 'tour-media' and is_company_member(((storage.foldername(name))[1])::uuid));

create policy "operators delete their own media"
  on storage.objects for delete to authenticated
  using (bucket_id = 'tour-media' and is_company_member(((storage.foldername(name))[1])::uuid));

-- Documents: the uploader and staff, nobody else. Never public, never listed.
create policy "operators upload their own documents"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'operator-documents'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "documents readable by owner and staff"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'operator-documents'
    and ((storage.foldername(name))[1] = auth.uid()::text or is_staff())
  );

-- ---------------------------------------------------------------------
-- 2. DAY-OF-TRAVEL OPERATIONS
-- ---------------------------------------------------------------------

-- The list a guide needs at the meeting point: who is coming, on what, with
-- which pickup, and whether they have already been checked in.
-- security_invoker is not optional here. A Postgres view runs with its
-- OWNER's privileges by default, so a view over an RLS-protected table hands
-- every row to every caller — a cross-tenant leak that the base table's
-- policies do nothing to stop. This was caught by 05_operations.sql, where a
-- rival operator could read another company's manifest.
create or replace view booking_manifest
with (security_invoker = true) as
select
  bi.id                as item_id,
  b.company_id,
  bi.tour_id,
  bi.departure_id,
  bi.starts_at,
  bi.seats,
  bi.pax_breakdown,
  bi.ticket_code,
  bi.redeemed_at,
  bi.pickup_note,
  b.id                 as booking_id,
  b.reference,
  b.status             as booking_status,
  b.guest_name,
  b.guest_phone,
  b.guest_email,
  b.guest_locale,
  b.grand_total,
  b.currency,
  pp.label             as pickup_point,
  b.created_at         as booked_at
from booking_items bi
join bookings b on b.id = bi.booking_id
left join tour_pickup_points pp on pp.id = bi.pickup_point_id
where b.status in ('confirmed', 'completed');

grant select on booking_manifest to authenticated;

/**
 * Check a traveller in at the meeting point.
 *
 * Idempotent: scanning the same QR twice returns the original timestamp
 * rather than overwriting it, because a guide will scan twice and the
 * question "were they actually here at 16:02 or 16:40" matters in a dispute.
 */
create or replace function redeem_ticket(p_ticket_code text)
returns table (item_id uuid, reference text, guest_name text, seats integer, already_redeemed boolean, redeemed_at timestamptz)
language plpgsql
security definer set search_path = public
as $$
declare
  v_item record;
begin
  -- Every table here carries FORCE ROW LEVEL SECURITY, which applies even
  -- inside a definer function. So a ticket belonging to another operator
  -- simply does not appear, and "not found" would tell a guide that a
  -- perfectly valid ticket is fake. The ownership check is therefore done
  -- against an unfiltered lookup first, so the two cases give two messages.
  if not exists (
    select 1 from booking_items bi
    join bookings b on b.id = bi.booking_id
    where bi.ticket_code = p_ticket_code
  ) then
    raise exception 'No booking matches that ticket' using errcode = 'no_data_found';
  end if;

  select bi.id, bi.redeemed_at, bi.seats, b.reference, b.guest_name, b.company_id, bi.starts_at
  into v_item
  from booking_items bi
  join bookings b on b.id = bi.booking_id
  where bi.ticket_code = p_ticket_code
    and b.status in ('confirmed', 'completed')
  for update;

  if not found then
    raise exception 'That ticket belongs to another operator, or the booking is not confirmed'
      using errcode = 'insufficient_privilege';
  end if;
  if not (is_company_member(v_item.company_id) or is_staff()) then
    raise exception 'That ticket belongs to another operator' using errcode = 'insufficient_privilege';
  end if;

  if v_item.redeemed_at is not null then
    return query select v_item.id, v_item.reference, v_item.guest_name, v_item.seats, true, v_item.redeemed_at;
    return;
  end if;

  update booking_items set redeemed_at = now() where id = v_item.id;

  return query select v_item.id, v_item.reference, v_item.guest_name, v_item.seats, false, now();
end;
$$;

/**
 * Marks past departures complete so payouts can include them and travellers
 * can be asked for a review. Run nightly.
 */
create or replace function complete_past_bookings()
returns integer
language plpgsql
security definer set search_path = public
as $$
declare v_count integer;
begin
  update bookings b
     set status = 'completed', completed_at = now()
   where b.status = 'confirmed'
     and not exists (
       select 1 from booking_items bi
       where bi.booking_id = b.id and bi.starts_at > now() - interval '12 hours'
     );
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- 3. REVIEW REPLIES
-- ---------------------------------------------------------------------
create or replace function reply_to_review(p_review_id uuid, p_reply text)
returns reviews
language plpgsql
security definer set search_path = public
as $$
declare
  v_review reviews;
begin
  select * into v_review from reviews where id = p_review_id for update;
  if not found then
    raise exception 'Review not found' using errcode = 'no_data_found';
  end if;
  if not (is_company_member(v_review.company_id) or is_staff()) then
    raise exception 'That review is on another operator''s listing' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(trim(p_reply), '') = '' then
    raise exception 'Write a reply before publishing it' using errcode = 'invalid_parameter_value';
  end if;

  update reviews
     set supplier_reply = p_reply, supplier_replied_at = now()
   where id = p_review_id
  returning * into v_review;

  return v_review;
end;
$$;

-- ---------------------------------------------------------------------
-- 4. PAYOUT STATEMENTS
-- What an operator is owed, and for which bookings. Computed from confirmed
-- and completed bookings that no payout has already claimed.
-- ---------------------------------------------------------------------
create or replace view payout_ledger
with (security_invoker = true) as
select
  b.company_id,
  b.currency,
  b.id                as booking_id,
  b.reference,
  b.created_at        as booked_at,
  bi.starts_at        as travel_at,
  b.grand_total,
  b.commission_total,
  b.supplier_net,
  b.status,
  (pi.payout_id is not null) as paid_out,
  po.status           as payout_status,
  po.paid_at
from bookings b
join lateral (
  select min(starts_at) as starts_at from booking_items where booking_id = b.id
) bi on true
left join payout_items pi on pi.booking_id = b.id
left join payouts po on po.id = pi.payout_id
where b.status in ('confirmed', 'completed', 'cancelled_by_user', 'cancelled_by_supplier');

grant select on payout_ledger to authenticated;

-- ---------------------------------------------------------------------
-- 5. MEDIA HOUSEKEEPING
-- ---------------------------------------------------------------------
-- Exactly one cover per tour. Promoting a new cover must demote the old one,
-- and doing that in the app leaves a window with two covers or none.
create or replace function set_tour_cover(p_tour_id uuid, p_media_id uuid)
returns void
language plpgsql
security definer set search_path = public
as $$
declare v_company uuid;
begin
  select company_id into v_company from tours where id = p_tour_id;
  if not (is_company_member(v_company) or is_staff()) then
    raise exception 'You do not have access to that listing' using errcode = 'insufficient_privilege';
  end if;

  update tour_media set is_cover = false where tour_id = p_tour_id and is_cover;
  update tour_media set is_cover = true where tour_id = p_tour_id and media_id = p_media_id;
end;
$$;

-- ---------- 0013_scheduled_jobs.sql ----------
-- =====================================================================
-- 0013_scheduled_jobs.sql
--
-- Moves recurring work from Vercel Cron into the database.
--
-- Two reasons, and the second matters more than the first:
--
--   1. Vercel's Hobby plan allows one cron run per DAY. The seat-hold reaper
--      has to run every minute — a hold expires after 15 minutes, and a
--      daily sweep would leave seats unsellable for up to 24 hours.
--
--   2. The reaper should not depend on the web tier being healthy. If the
--      site is down, inventory should still be released. pg_cron runs inside
--      Postgres, so it keeps working when nothing else does.
--
-- The /api/cron/* routes stay in place as a manual trigger and as a fallback
-- for anyone who prefers Vercel Cron on a paid plan.
-- =====================================================================

-- pg_cron must be enabled once per project:
--   Supabase Dashboard → Database → Extensions → enable "pg_cron"
--
-- A bare `create extension` would abort this whole migration on a project
-- where it is unavailable, so the failure is caught and reported instead.
do $$
begin
  create extension if not exists pg_cron with schema extensions;
exception when others then
  raise notice 'pg_cron unavailable (%). Jobs will not be scheduled — see the notice below.', sqlerrm;
end $$;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice '---------------------------------------------------------------';
    raise notice 'pg_cron is NOT enabled, so nothing is scheduled.';
    raise notice 'Enable it: Dashboard -> Database -> Extensions -> pg_cron,';
    raise notice 'then run this migration again.';
    raise notice 'Until then, seats held by abandoned checkouts are never released.';
    raise notice '---------------------------------------------------------------';
    return;
  end if;

  -- Release seats from abandoned checkouts. Every minute, because a traveller
  -- who abandons at 14:00 should not block a sale at 14:16.
  perform cron.unschedule('expire-stale-holds') where exists (
    select 1 from cron.job where jobname = 'expire-stale-holds');
  perform cron.schedule('expire-stale-holds', '* * * * *',
    $job$select public.expire_stale_holds()$job$);

  -- Popularity feeds ranking on every listing page. Nightly is plenty.
  perform cron.unschedule('refresh-popularity') where exists (
    select 1 from cron.job where jobname = 'refresh-popularity');
  perform cron.schedule('refresh-popularity', '15 2 * * *',
    $job$select public.refresh_popularity_scores()$job$);

  -- Homepage counters.
  perform cron.unschedule('refresh-homepage-stats') where exists (
    select 1 from cron.job where jobname = 'refresh-homepage-stats');
  perform cron.schedule('refresh-homepage-stats', '5 * * * *',
    $job$select public.refresh_homepage_stats()$job$);

  -- Mark past departures complete so payouts can include them and travellers
  -- can be asked for a review.
  perform cron.unschedule('complete-past-bookings') where exists (
    select 1 from cron.job where jobname = 'complete-past-bookings');
  perform cron.schedule('complete-past-bookings', '30 3 * * *',
    $job$select public.complete_past_bookings()$job$);

  raise notice 'Scheduled 4 jobs. Check them with: select jobname, schedule from cron.job;';
end $$;

-- Confirms the jobs are alive and succeeding:
--   select * from scheduled_job_status;
-- Created only when pg_cron exists, since it reads cron's own tables.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    execute $view$
      create or replace view scheduled_job_status
      with (security_invoker = true) as
      select j.jobname, j.schedule, j.active,
             d.status as last_status, d.start_time as last_run, d.return_message
      from cron.job j
      left join lateral (
        select status, start_time, return_message
        from cron.job_run_details
        where jobid = j.jobid
        order by start_time desc limit 1
      ) d on true
    $view$;
  end if;
end $$;

-- ---------- 0014_cms_editor_and_crm.sql ----------
-- =====================================================================
-- 0014_cms_editor_and_crm.sql
--
-- Turns the CMS tables into something a marketing team can actually run:
-- per-entry SEO, custom CSS, custom JSON-LD, scheduled publishing, and the
-- CRM objects an admin panel needs (leads, claims, saved reports).
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. THE UNIVERSAL EDITOR FIELDS
-- Every editable entity gets the same set, so one editor component can
-- drive posts, pages, locations and services without special cases.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['blog_post_translations', 'cms_page_translations']
  loop
    execute format($sql$
      alter table %I
        add column if not exists canonical_url  text,
        add column if not exists robots         text default 'index,follow',
        add column if not exists og_title       text,
        add column if not exists og_description text,
        add column if not exists focus_keyword  text
    $sql$, t);
  end loop;
end $$;

alter table blog_posts
  add column if not exists custom_css        text,
  add column if not exists custom_schema     jsonb,
  add column if not exists custom_head       text,
  add column if not exists scheduled_for     timestamptz,
  add column if not exists featured_position smallint,
  add column if not exists is_featured       boolean not null default false,
  add column if not exists allow_comments    boolean not null default false,
  add column if not exists updated_by        uuid references profiles(id) on delete set null;

alter table cms_pages
  add column if not exists custom_css    text,
  add column if not exists custom_schema jsonb,
  add column if not exists custom_head   text,
  add column if not exists scheduled_for timestamptz,
  add column if not exists cover_media_id uuid references media_assets(id) on delete set null;

-- Scheduled publishing. A post with a future `scheduled_for` goes live on its
-- own — without this the "schedule" field is a lie that needs a human at 6am.
create or replace function publish_scheduled_content()
returns integer
language plpgsql
security definer set search_path = public
as $$
declare v_total integer := 0; v_count integer;
begin
  update blog_posts
     set status = 'published', published_at = coalesce(published_at, scheduled_for)
   where status = 'scheduled' and scheduled_for <= now();
  get diagnostics v_count = row_count;
  v_total := v_total + v_count;

  update cms_pages
     set status = 'published', published_at = coalesce(published_at, scheduled_for)
   where status = 'scheduled' and scheduled_for <= now();
  get diagnostics v_count = row_count;
  return v_total + v_count;
end;
$$;

-- ---------------------------------------------------------------------
-- 2. LEADS
-- Enquiries that are not bookings: partner interest, group quotes,
-- corporate requests. The commercial pipeline an operator marketplace
-- needs alongside transactional bookings.
-- ---------------------------------------------------------------------
create type lead_status as enum ('new', 'contacted', 'qualified', 'won', 'lost', 'spam');
create type lead_source as enum ('contact_form', 'group_quote', 'partner_enquiry', 'newsletter', 'phone', 'whatsapp', 'import', 'other');

create table leads (
  id            uuid primary key default gen_random_uuid(),
  status        lead_status not null default 'new',
  source        lead_source not null default 'contact_form',
  name          text not null,
  email         citext,
  phone         text,
  company_name  text,
  message       text,
  country_id    uuid references countries(id) on delete set null,
  city_id       uuid references cities(id) on delete set null,
  tour_id       uuid references tours(id) on delete set null,
  party_size    smallint,
  travel_date   date,
  estimated_value numeric(12,2),
  currency      currency_code,
  assigned_to   uuid references profiles(id) on delete set null,
  utm           jsonb not null default '{}'::jsonb,
  landing_page  text,
  notes         text,
  contacted_at  timestamptz,
  closed_at     timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint leads_reachable check (email is not null or phone is not null)
);
create index leads_pipeline_idx on leads (status, created_at desc);
create index leads_assigned_idx on leads (assigned_to) where status in ('new','contacted','qualified');

create table lead_events (
  id         bigint generated always as identity primary key,
  lead_id    uuid not null references leads(id) on delete cascade,
  actor_id   uuid references profiles(id) on delete set null,
  kind       text not null check (kind in ('note','call','email','whatsapp','status_change','assignment')),
  body       text,
  created_at timestamptz not null default now()
);
create index lead_events_idx on lead_events (lead_id, created_at desc);

create trigger touch_leads before update on leads
  for each row execute function internal.touch_updated_at();

-- ---------------------------------------------------------------------
-- 3. LISTING CLAIMS
-- Someone asserting they own a listing we created or imported. Approving a
-- claim hands over a live listing, so it is an admin decision with a trail.
-- ---------------------------------------------------------------------
create type claim_status as enum ('pending', 'approved', 'rejected', 'withdrawn');

create table listing_claims (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references companies(id) on delete cascade,
  claimant_id   uuid not null references profiles(id) on delete cascade,
  status        claim_status not null default 'pending',
  evidence      text not null,
  evidence_urls text[] not null default '{}',
  contact_email citext not null,
  contact_phone text,
  reviewed_by   uuid references profiles(id) on delete set null,
  reviewed_at   timestamptz,
  decision_note text,
  created_at    timestamptz not null default now(),
  unique (company_id, claimant_id)
);
create index claims_queue_idx on listing_claims (status, created_at) where status = 'pending';

create or replace function approve_listing_claim(p_claim_id uuid, p_note text default null)
returns listing_claims
language plpgsql
security definer set search_path = public
as $$
declare v_claim listing_claims;
begin
  if not is_admin() then
    raise exception 'Only an administrator can approve a claim' using errcode = 'insufficient_privilege';
  end if;

  select * into v_claim from listing_claims where id = p_claim_id for update;
  if not found then
    raise exception 'Claim not found' using errcode = 'no_data_found';
  end if;
  if v_claim.status = 'approved' then
    return v_claim;  -- idempotent
  end if;

  -- Approving grants control of a live business listing, so it is the same
  -- privileged transition as approving an application: membership plus role.
  insert into company_members (company_id, profile_id, role, permissions, accepted_at)
  values (v_claim.company_id, v_claim.claimant_id, 'company_owner',
          array['tours.write','bookings.read','payouts.read','staff.write'], now())
  on conflict (company_id, profile_id) do nothing;

  update profiles set role = 'company_owner'
   where id = v_claim.claimant_id and role = 'traveler';

  update listing_claims
     set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(), decision_note = p_note
   where id = p_claim_id
  returning * into v_claim;

  insert into audit_logs (actor_id, actor_role, action, entity_type, entity_id, after)
  values (auth.uid(), auth_role(), 'listing_claim.approve', 'company', v_claim.company_id,
          jsonb_build_object('claim_id', p_claim_id, 'claimant', v_claim.claimant_id));

  return v_claim;
end;
$$;

-- ---------------------------------------------------------------------
-- 4. THEME AND SITE-WIDE SETTINGS
-- Stored as settings rows rather than columns so the admin can add a key
-- without a migration.
-- ---------------------------------------------------------------------
insert into site_settings (key, value, description) values
  ('theme', '{"primary":"#0E6E64","accent":"#B98A2E","urgent":"#C2334E","ink":"#0B1F1C","surface":"#EFF2F1","radius":"22px","font_display":"Fraunces","font_body":"Be Vietnam Pro"}', 'Colour and type tokens applied site-wide'),
  ('custom_css', '{"css":""}', 'Custom CSS injected on every page'),
  ('robots_txt', '{"extra_rules":"","noindex_site":false}', 'Additions to the generated robots.txt'),
  ('sitemap', '{"exclude_paths":[],"changefreq_override":null}', 'Sitemap generation overrides'),
  ('contact', '{"email":"help@travelhubgulf.com","phone":"","whatsapp":"","address":""}', 'Public contact details')
on conflict (key) do nothing;

-- ---------------------------------------------------------------------
-- 5. SAVED REPORTS
-- ---------------------------------------------------------------------
create table saved_reports (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  kind        text not null check (kind in ('revenue','bookings','listings','leads','seo','operators')),
  filters     jsonb not null default '{}'::jsonb,
  created_by  uuid references profiles(id) on delete set null,
  is_shared   boolean not null default false,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------
-- 6. RLS
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['leads','lead_events','listing_claims','saved_reports']
  loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
  end loop;
end $$;

-- Leads are commercial data: staff only, both directions.
create policy leads_staff on leads for all using (is_staff()) with check (is_staff());
create policy lead_events_staff on lead_events for all using (is_staff()) with check (is_staff());
create policy reports_staff on saved_reports for all using (is_staff()) with check (is_staff());

-- Anyone signed in may file a claim; only they and staff can see it.
create policy claims_own_read on listing_claims for select
  using (claimant_id = auth.uid() or is_staff());
create policy claims_insert on listing_claims for insert
  with check (claimant_id = auth.uid());
create policy claims_staff_write on listing_claims for update
  using (is_staff()) with check (is_staff());

-- The public contact form writes leads through the service role, never
-- directly — an anon insert policy here would be a spam funnel.

-- ---------- 0015_directory_verticals.sql ----------
-- =====================================================================
-- 0015_directory_verticals.sql
--
-- Turns the site from a tours-only marketplace into a multi-vertical
-- directory: hotels, attractions, malls, things to do — plus tours.
--
-- THE MODELLING DECISION
--
-- A tour is bookable: it has departures, seats, per-pax pricing and a
-- cancellation policy. A mall has none of those. Adding hotels and malls to
-- `tours` would mean every query, every card and every page asking "does
-- this row actually sell anything?", and the booking engine would slowly
-- fill with null checks.
--
-- So `points_of_interest` is promoted from a thin "nearby" helper into a
-- full directory listing, and `tours` stays the bookable subtype. They share
-- geography, reviews, media and SEO; they differ where they genuinely differ.
--
-- A tour therefore appears in the directory through its own tables, and a
-- hotel appears through `points_of_interest`. Both are searchable by
-- destination and vertical; only one can take a seat reservation.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. VERTICALS — the top-level tabs on a destination page
-- ---------------------------------------------------------------------
create table verticals (
  id           uuid primary key default gen_random_uuid(),
  code         text not null unique,      -- 'tours', 'hotels', 'attractions'
  -- Whether this vertical books through us or hands off to the operator.
  -- Tours transact; hotels and malls generate enquiries. Getting this wrong
  -- means promising a booking flow that does not exist.
  fulfilment   text not null default 'enquiry'
               check (fulfilment in ('booking', 'enquiry', 'affiliate', 'info_only')),
  icon         text,
  position     smallint not null default 0,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now()
);

create table vertical_translations (
  vertical_id      uuid not null references verticals(id) on delete cascade,
  locale           locale_code not null,
  name             text not null,          -- "Hotels"
  slug             text not null,          -- "hotels"
  plural_label     text,                   -- "hotels in Dubai"
  intro            text,
  meta_title       text,
  meta_description text,
  primary key (vertical_id, locale)
);
create unique index vertical_slug_uq on vertical_translations (locale, slug);

-- ---------------------------------------------------------------------
-- 2. LISTINGS — points_of_interest, promoted
-- ---------------------------------------------------------------------
alter table points_of_interest
  add column if not exists vertical_id   uuid references verticals(id) on delete restrict,
  add column if not exists company_id    uuid references companies(id) on delete set null,
  add column if not exists status        listing_status not null default 'published',
  add column if not exists price_level   smallint check (price_level between 1 and 4),
  add column if not exists price_from    numeric(12,2),
  add column if not exists currency      currency_code,
  add column if not exists rating_count  integer not null default 0,
  add column if not exists phone         text,
  add column if not exists website       text,
  add column if not exists booking_url   text,
  add column if not exists opening_hours jsonb not null default '{}'::jsonb,
  -- Filter facets. jsonb keeps a hotel's "pool, spa, airport shuttle" and a
  -- mall's "cinema, food court" in one queryable shape without a column per
  -- vertical, and GIN makes containment queries fast.
  add column if not exists amenities     text[] not null default '{}',
  add column if not exists attributes    jsonb not null default '{}'::jsonb,
  add column if not exists is_featured   boolean not null default false,
  add column if not exists is_claimed    boolean not null default false,
  add column if not exists popularity_score numeric(10,4) not null default 0,
  add column if not exists updated_at    timestamptz not null default now();

alter table poi_translations
  add column if not exists description      text,
  add column if not exists body             text,
  add column if not exists highlights       text[] not null default '{}',
  add column if not exists meta_title       text,
  add column if not exists meta_description text;

create index if not exists poi_vertical_idx on points_of_interest (vertical_id, city_id)
  where is_active and status = 'published';
create index if not exists poi_amenities_gin on points_of_interest using gin (amenities);
create index if not exists poi_attributes_gin on points_of_interest using gin (attributes);
create index if not exists poi_price_idx on points_of_interest (city_id, price_from);
create index if not exists poi_rating_idx on points_of_interest (city_id, rating desc);

create trigger touch_poi before update on points_of_interest
  for each row execute function internal.touch_updated_at();

-- ---------------------------------------------------------------------
-- 3. ENQUIRIES
-- Verticals that do not transact still capture demand. The requirements a
-- traveller types here are the whole product for lead-gen verticals, so they
-- are structured rather than dumped into a free-text blob.
-- ---------------------------------------------------------------------
alter table leads
  add column if not exists listing_id   uuid references points_of_interest(id) on delete set null,
  add column if not exists vertical_id  uuid references verticals(id) on delete set null,
  add column if not exists requirements jsonb not null default '{}'::jsonb,
  add column if not exists preferred_contact text
    check (preferred_contact in ('email', 'phone', 'whatsapp'));

create index if not exists leads_listing_idx on leads (listing_id) where listing_id is not null;

-- ---------------------------------------------------------------------
-- 4. DIRECTORY SEARCH VIEW
-- One flat row per (listing, locale), mirroring tour_search_index so the
-- listing page can query either with the same shape.
-- ---------------------------------------------------------------------
create or replace view directory_listings
with (security_invoker = true) as
select
  p.id,
  pt.locale,
  pt.name,
  pt.slug,
  pt.summary,
  pt.description,
  p.kind,
  p.vertical_id,
  vt.slug            as vertical_slug,
  vt.name            as vertical_name,
  p.city_id,
  ct.name            as city_name,
  ct.slug            as city_slug,
  c.id               as country_id,
  cot.name           as country_name,
  cot.slug           as country_slug,
  p.address,
  p.location,
  p.rating,
  p.rating_count,
  p.price_level,
  p.price_from,
  p.currency,
  p.amenities,
  p.attributes,
  p.image_url,
  p.phone,
  p.website,
  p.booking_url,
  p.opening_hours,
  p.is_featured,
  p.is_claimed,
  p.popularity_score,
  p.company_id
from points_of_interest p
join poi_translations pt on pt.poi_id = p.id
join cities ci on ci.id = p.city_id
join city_translations ct on ct.city_id = ci.id and ct.locale = pt.locale
join countries c on c.id = ci.country_id
join country_translations cot on cot.country_id = c.id and cot.locale = pt.locale
left join verticals v on v.id = p.vertical_id
left join vertical_translations vt on vt.vertical_id = v.id and vt.locale = pt.locale
where p.is_active and p.status = 'published';

grant select on directory_listings to anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. FACET COUNTS
-- Filter sidebars need "Pool (42)". Counting in the app means pulling every
-- row; this does it in the database and returns only the counts.
-- ---------------------------------------------------------------------
create or replace function directory_facets(
  p_city_id     uuid,
  p_vertical_id uuid default null,
  p_locale      locale_code default 'en'
)
returns table (facet text, value text, count bigint)
language sql
stable
as $$
  with scope as (
    select p.* from points_of_interest p
    where p.city_id = p_city_id
      and p.is_active and p.status = 'published'
      and (p_vertical_id is null or p.vertical_id = p_vertical_id)
  )
  select 'amenity'::text, a.amenity, count(*)
  from scope, unnest(scope.amenities) as a(amenity)
  group by a.amenity
  union all
  select 'price_level'::text, price_level::text, count(*)
  from scope where price_level is not null
  group by price_level
  union all
  select 'rating'::text,
         case when rating >= 4.5 then '4.5' when rating >= 4 then '4.0'
              when rating >= 3.5 then '3.5' else 'any' end,
         count(*)
  from scope where rating is not null
  group by 1, 2
  order by 1, 3 desc;
$$;

-- ---------------------------------------------------------------------
-- 6. SEED THE VERTICALS
-- ---------------------------------------------------------------------
insert into verticals (code, fulfilment, icon, position) values
  ('tours',        'booking', 'compass',  0),
  ('things-to-do', 'booking', 'sparkles', 1),
  ('attractions',  'enquiry', 'landmark', 2),
  ('hotels',       'enquiry', 'bed',      3),
  ('malls',        'info_only', 'shopping-bag', 4),
  ('restaurants',  'info_only', 'utensils', 5)
on conflict (code) do nothing;

insert into vertical_translations (vertical_id, locale, name, slug, plural_label, intro, meta_title, meta_description)
select v.id, x.locale::locale_code, x.name, x.slug, x.plural, x.intro, x.meta_title, x.meta_desc
from verticals v
join (values
  ('tours','en','Tours','tours','tours','Guided tours and day trips, bookable with instant confirmation.',
   'Tours in %s | Book Online','Book guided tours and day trips in %s. Verified operators, free cancellation.'),
  ('tours','ar','جولات','جولات','جولات','جولات سياحية ورحلات يومية بتأكيد فوري.',
   'جولات في %s | احجز الآن','احجز جولات ورحلات يومية في %s. مشغلون معتمدون وإلغاء مجاني.'),
  ('things-to-do','en','Things to do','things-to-do','experiences','Everything worth doing, from desert safaris to water parks.',
   'Things to Do in %s | Tickets & Tours','Find things to do in %s — attractions, tours and experiences with instant confirmation.'),
  ('attractions','en','Attractions','attractions','attractions','Landmarks, museums and the sights worth planning a day around.',
   'Attractions in %s | Tickets & Opening Hours','Top attractions in %s with opening hours, prices and how to get there.'),
  ('hotels','en','Hotels','hotels','hotels','Where to stay, from beach resorts to city apartments.',
   'Hotels in %s | Where to Stay','Find hotels in %s by area, price and amenities.'),
  ('malls','en','Malls','malls','malls','Shopping centres, outlets and souqs.',
   'Malls in %s | Shopping Guide','Shopping malls and souqs in %s with opening hours and what is inside.'),
  ('restaurants','en','Restaurants','restaurants','restaurants','Where to eat, by cuisine and neighbourhood.',
   'Restaurants in %s | Where to Eat','Restaurants in %s by cuisine, price and area.')
) as x(code, locale, name, slug, plural, intro, meta_title, meta_desc) on x.code = v.code
on conflict do nothing;

-- Existing POI rows predate verticals; map them by their `kind`.
update points_of_interest p
   set vertical_id = v.id
  from verticals v
 where p.vertical_id is null
   and v.code = case p.kind
     when 'hotel' then 'hotels'
     when 'mall' then 'malls'
     when 'restaurant' then 'restaurants'
     else 'attractions'
   end;

-- ---------- 0016_regions.sql ----------
-- =====================================================================
-- 0016_regions.sql — PHASE 2 (part 1): the missing hierarchy level.
--
-- Dubai is both an emirate and a city. Abu Dhabi emirate contains Al Ain.
-- Without a region layer there is no way to express "everything in Sharjah
-- emirate", and no URL for it. Retrofitting a hierarchy level after the URLs
-- are indexed means rewriting every one of them, so it goes in now.
--
--   country → region → city → area → listing
-- =====================================================================

create table regions (
  id          uuid primary key default gen_random_uuid(),
  country_id  uuid not null references countries(id) on delete restrict,
  code        text,                          -- 'AE-DU', 'SA-01'
  kind        text not null default 'emirate'
              check (kind in ('emirate', 'province', 'governorate', 'region', 'municipality')),
  centroid    geography(point, 4326),
  is_active   boolean not null default true,
  priority    smallint not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (country_id, code)
);
create index regions_country_idx on regions (country_id) where is_active;

create table region_translations (
  region_id        uuid not null references regions(id) on delete cascade,
  locale           locale_code not null,
  name             text not null,
  slug             text not null,
  tagline          text,
  intro            text,
  body             text,
  meta_title       text,
  meta_description text,
  primary key (region_id, locale)
);
create unique index region_slug_uq on region_translations (locale, slug);

alter table cities add column if not exists region_id uuid references regions(id) on delete set null;
create index if not exists cities_region_idx on cities (region_id);

create trigger touch_regions before update on regions
  for each row execute function internal.touch_updated_at();

alter table regions enable row level security;
alter table regions force row level security;
alter table region_translations enable row level security;
alter table region_translations force row level security;

create policy regions_public_read on regions for select using (true);
create policy regions_staff_write on regions for all using (is_staff()) with check (is_staff());
create policy region_tr_public_read on region_translations for select using (true);
create policy region_tr_staff_write on region_translations for all using (is_staff()) with check (is_staff());

-- ---------------------------------------------------------------------
-- No data here on purpose.
--
-- The region backfill needs countries and cities to exist, and migrations run
-- before the seed. Data belongs in supabase/seed/seed.sql, which is where the
-- emirates and the city→region mapping now live.
-- ---------------------------------------------------------------------

-- ---------- 0017_listing_spine.sql ----------
-- =====================================================================
-- 0017_listing_spine.sql — PHASE 0: the three-layer spine.
--
--   BUSINESS  → the legal entity (companies)
--   LISTING   → the page a traveller lands on   ← this migration
--   PRODUCT   → the sellable unit (tour_options)
--
-- WHY ADDITIVE, NOT A REWRITE
--
-- 26 foreign keys already point at tours, tour_options and tour_departures,
-- and the booking engine on top of them is attack-tested. So `listings`
-- becomes the PARENT page entity and `tours` becomes its booking extension,
-- linked 1:1. Nothing that works today breaks; everything gains one shared
-- identity for pages, reviews, media, filters and SEO.
--
-- A mall is a listing with no extension. A hotel is a listing with no
-- extension and enquiry fulfilment. A desert safari is a listing WITH a
-- tours extension, and only that one can hold a seat reservation.
-- =====================================================================

create table listings (
  id            uuid primary key default gen_random_uuid(),
  vertical_id   uuid not null references verticals(id) on delete restrict,
  business_id   uuid references companies(id) on delete set null,

  country_id    uuid not null references countries(id) on delete restrict,
  region_id     uuid references regions(id) on delete set null,
  city_id       uuid not null references cities(id) on delete restrict,
  area_id       uuid references areas(id) on delete set null,
  location      geography(point, 4326),
  address       text,

  status        listing_status not null default 'draft',
  -- Overrides the vertical default. A hotel that signs up for real-time
  -- booking becomes 'booking' without moving vertical.
  fulfilment    text check (fulfilment in ('booking','enquiry','affiliate','info_only')),

  -- Denormalised, read-hot, maintained by triggers and jobs.
  price_from       numeric(12,2),
  price_level      smallint check (price_level between 1 and 4),
  currency         currency_code,
  rating_avg       numeric(3,2) not null default 0,
  rating_count     integer not null default 0,
  popularity_score numeric(10,4) not null default 0,
  is_featured      boolean not null default false,
  is_claimed       boolean not null default false,

  amenities     text[] not null default '{}',
  attributes    jsonb not null default '{}'::jsonb,

  -- Where this listing's detail lives. Exactly one may be set.
  tour_id       uuid references tours(id) on delete cascade,
  poi_id        uuid references points_of_interest(id) on delete cascade,

  published_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint listing_single_source check (num_nonnulls(tour_id, poi_id) <= 1)
);

create unique index listings_tour_uq on listings (tour_id) where tour_id is not null;
create unique index listings_poi_uq  on listings (poi_id)  where poi_id  is not null;
create index listings_browse_idx on listings (city_id, vertical_id, status)
  where status = 'published';
create index listings_region_idx on listings (region_id) where status = 'published';
create index listings_amenities_gin on listings using gin (amenities);
create index listings_attributes_gin on listings using gin (attributes);
create index listings_location_gix on listings using gist (location);
create index listings_price_idx on listings (city_id, price_from) where status = 'published';

create table listing_translations (
  listing_id       uuid not null references listings(id) on delete cascade,
  locale           locale_code not null,
  name             text not null,
  slug             text not null,
  summary          text,
  description      text,
  body             text,
  highlights       text[] not null default '{}',
  meta_title       text,
  meta_description text,
  primary key (listing_id, locale)
);

-- URL NAMESPACE
--
-- /{country}/{city}/{vertical}/{slug} — the last segment is either a category
-- or a listing. Rather than hoping they never collide, the collision is made
-- impossible: a listing slug must be unique within its city and locale, and
-- must not match a category slug in that locale.
create unique index listing_slug_uq on listing_translations (locale, slug);

create or replace function internal.guard_listing_slug()
returns trigger
language plpgsql
as $$
begin
  if exists (
    select 1 from category_translations ct
    where ct.locale = new.locale and ct.slug = new.slug
  ) then
    raise exception 'The slug "%" is already used by a category. Categories and listings share a URL segment, so pick another.', new.slug
      using errcode = 'unique_violation';
  end if;
  return new;
end;
$$;

create trigger guard_listing_slug
  before insert or update of slug on listing_translations
  for each row execute function internal.guard_listing_slug();

create trigger touch_listings before update on listings
  for each row execute function internal.touch_updated_at();

-- ---------------------------------------------------------------------
-- SYNC
-- A tour or POI edited through its own tables must keep its listing row in
-- step. Doing this in application code guarantees the two drift apart the
-- first time someone writes a script.
-- ---------------------------------------------------------------------
create or replace function internal.sync_listing_from_tour()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
declare
  v_listing uuid;
  v_country uuid;
  v_region  uuid;
begin
  select ci.country_id, ci.region_id into v_country, v_region
  from cities ci where ci.id = new.city_id;

  insert into listings (
    vertical_id, business_id, country_id, region_id, city_id, area_id,
    location, status, fulfilment, price_from, currency,
    rating_avg, rating_count, popularity_score, tour_id, published_at
  )
  select (select id from verticals where code = 'tours'),
         new.company_id, v_country, v_region, new.city_id, new.area_id,
         new.meeting_point, new.status, 'booking', new.from_price, new.base_currency,
         new.rating_avg, new.rating_count, new.popularity_score, new.id, new.published_at
  on conflict (tour_id) where tour_id is not null
  do update set
    business_id = excluded.business_id, city_id = excluded.city_id,
    region_id = excluded.region_id, area_id = excluded.area_id,
    location = excluded.location, status = excluded.status,
    price_from = excluded.price_from, currency = excluded.currency,
    rating_avg = excluded.rating_avg, rating_count = excluded.rating_count,
    popularity_score = excluded.popularity_score, published_at = excluded.published_at
  returning id into v_listing;

  insert into listing_translations (listing_id, locale, name, slug, summary, description, highlights, meta_title, meta_description)
  select v_listing, tt.locale, tt.title, tt.slug, tt.summary, tt.description,
         tt.highlights, tt.meta_title, tt.meta_description
  from tour_translations tt where tt.tour_id = new.id
  on conflict (listing_id, locale) do update set
    name = excluded.name, slug = excluded.slug, summary = excluded.summary,
    description = excluded.description, highlights = excluded.highlights,
    meta_title = excluded.meta_title, meta_description = excluded.meta_description;

  return null;
end;
$$;

create trigger sync_listing_on_tour after insert or update on tours
  for each row execute function internal.sync_listing_from_tour();

create or replace function internal.sync_listing_from_poi()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
declare
  v_listing uuid;
  v_country uuid;
  v_region  uuid;
begin
  select ci.country_id, ci.region_id into v_country, v_region
  from cities ci where ci.id = new.city_id;

  insert into listings (
    vertical_id, business_id, country_id, region_id, city_id, area_id,
    location, address, status, price_from, price_level, currency,
    rating_avg, rating_count, amenities, attributes,
    is_featured, is_claimed, popularity_score, poi_id
  )
  values (
    new.vertical_id, new.company_id, v_country, v_region, new.city_id, new.area_id,
    new.location, new.address, new.status, new.price_from, new.price_level, new.currency,
    coalesce(new.rating, 0), new.rating_count, new.amenities, new.attributes,
    new.is_featured, new.is_claimed, new.popularity_score, new.id
  )
  on conflict (poi_id) where poi_id is not null
  do update set
    vertical_id = excluded.vertical_id, business_id = excluded.business_id,
    city_id = excluded.city_id, region_id = excluded.region_id,
    location = excluded.location, address = excluded.address, status = excluded.status,
    price_from = excluded.price_from, price_level = excluded.price_level,
    currency = excluded.currency, rating_avg = excluded.rating_avg,
    rating_count = excluded.rating_count, amenities = excluded.amenities,
    attributes = excluded.attributes, is_featured = excluded.is_featured,
    is_claimed = excluded.is_claimed
  returning id into v_listing;

  insert into listing_translations (listing_id, locale, name, slug, summary, description, body, highlights, meta_title, meta_description)
  select v_listing, pt.locale, pt.name, pt.slug, pt.summary, pt.description,
         pt.body, pt.highlights, pt.meta_title, pt.meta_description
  from poi_translations pt where pt.poi_id = new.id
  on conflict (listing_id, locale) do update set
    name = excluded.name, slug = excluded.slug, summary = excluded.summary,
    description = excluded.description, body = excluded.body,
    highlights = excluded.highlights, meta_title = excluded.meta_title,
    meta_description = excluded.meta_description;

  return null;
end;
$$;

create trigger sync_listing_on_poi after insert or update on points_of_interest
  for each row execute function internal.sync_listing_from_poi();

-- Translations edited directly must propagate too.
create or replace function internal.sync_listing_translation()
returns trigger
language plpgsql
security definer set search_path = public, internal
as $$
begin
  if tg_table_name = 'tour_translations' then
    perform internal.sync_listing_from_tour() from tours where id = new.tour_id;
    update listing_translations lt
       set name = new.title, slug = new.slug, summary = new.summary,
           description = new.description, highlights = new.highlights,
           meta_title = new.meta_title, meta_description = new.meta_description
      from listings l
     where l.tour_id = new.tour_id and lt.listing_id = l.id and lt.locale = new.locale;
  else
    update listing_translations lt
       set name = new.name, slug = new.slug, summary = new.summary,
           description = new.description, body = new.body,
           meta_title = new.meta_title, meta_description = new.meta_description
      from listings l
     where l.poi_id = new.poi_id and lt.listing_id = l.id and lt.locale = new.locale;
  end if;
  return null;
end;
$$;

create trigger sync_listing_tr_poi after insert or update on poi_translations
  for each row execute function internal.sync_listing_translation();

-- ---------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------
alter table listings enable row level security;
alter table listings force row level security;
alter table listing_translations enable row level security;
alter table listing_translations force row level security;

create policy listings_public_read on listings for select
  using (status = 'published' or is_company_member(business_id) or is_staff());
create policy listings_owner_write on listings for all
  using (is_company_member(business_id) or is_staff())
  with check (is_company_member(business_id) or is_staff());

create policy listing_tr_read on listing_translations for select using (
  exists (select 1 from listings l where l.id = listing_translations.listing_id
          and (l.status = 'published' or is_company_member(l.business_id) or is_staff())));
create policy listing_tr_write on listing_translations for all using (
  exists (select 1 from listings l where l.id = listing_translations.listing_id
          and (is_company_member(l.business_id) or is_staff())))
  with check (
  exists (select 1 from listings l where l.id = listing_translations.listing_id
          and (is_company_member(l.business_id) or is_staff())));

-- ---------------------------------------------------------------------
-- THE UNIFIED READ MODEL
-- One relation the whole front end queries, whatever the vertical.
-- ---------------------------------------------------------------------
create or replace view listing_index
with (security_invoker = true) as
select
  l.id, lt.locale, lt.name, lt.slug, lt.summary, lt.description,
  l.vertical_id, vt.slug as vertical_slug, vt.name as vertical_name,
  coalesce(l.fulfilment, v.fulfilment) as fulfilment,
  l.country_id, cot.slug as country_slug, cot.name as country_name,
  l.region_id, rt.slug as region_slug, rt.name as region_name,
  l.city_id, ct.slug as city_slug, ct.name as city_name,
  l.business_id, l.address, l.location,
  l.price_from, l.price_level, l.currency,
  l.rating_avg, l.rating_count, l.popularity_score,
  l.amenities, l.attributes, l.is_featured, l.is_claimed,
  l.tour_id, l.poi_id, l.status, l.published_at
from listings l
join listing_translations lt on lt.listing_id = l.id
join verticals v on v.id = l.vertical_id
left join vertical_translations vt on vt.vertical_id = v.id and vt.locale = lt.locale
join countries co on co.id = l.country_id
left join country_translations cot on cot.country_id = co.id and cot.locale = lt.locale
left join regions r on r.id = l.region_id
left join region_translations rt on rt.region_id = r.id and rt.locale = lt.locale
join cities ci on ci.id = l.city_id
left join city_translations ct on ct.city_id = ci.id and ct.locale = lt.locale
where l.status = 'published';

grant select on listing_index to anon, authenticated;

-- Backfills every existing tour and POI by touching them, which fires the
-- sync triggers above. Safe to re-run.
create or replace function backfill_listings()
returns text
language plpgsql
security definer set search_path = public
as $$
declare v_tours int; v_poi int;
begin
  update tours set updated_at = now();
  get diagnostics v_tours = row_count;
  update points_of_interest set updated_at = now();
  get diagnostics v_poi = row_count;
  return format('Synced %s tours and %s places into listings.', v_tours, v_poi);
end;
$$;

-- ---------- 0018_auth_roles_rbac.sql ----------
-- =====================================================================
-- 0018_auth_roles_rbac.sql — PHASE 1: authentication and authorization.
--
-- Ten roles, a data-driven permission matrix, and account status.
--
-- The five existing roles are RENAMED rather than replaced. `ALTER TYPE ...
-- RENAME VALUE` rewrites every stored row and every foreign reference
-- atomically, so no data migration is needed and no row is ever left holding
-- a role that no longer exists. Function bodies are a different matter —
-- plpgsql stores them as text, so every function containing an old literal
-- is recreated below.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. THE TEN ROLES
-- ---------------------------------------------------------------------
alter type user_role rename value 'traveler'       to 'customer';
alter type user_role rename value 'company_owner'  to 'business_owner';
alter type user_role rename value 'company_staff'  to 'business_staff';
alter type user_role rename value 'editor'         to 'content_manager';
alter type user_role rename value 'support'        to 'support_agent';

-- ADD VALUE cannot run in the same transaction as a use of the new value,
-- which is why the seeding of role_permissions is a separate statement below.
alter type user_role add value if not exists 'booking_manager' after 'content_manager';
alter type user_role add value if not exists 'tour_operator'   after 'business_staff';
alter type user_role add value if not exists 'hotel_manager'   after 'tour_operator';

-- Defaults referenced the old names as text.
alter table profiles       alter column role set default 'customer';
alter table company_members alter column role set default 'business_staff';

-- ---------------------------------------------------------------------
-- 2. ACCOUNT STATUS
-- A role says what you may do. Status says whether you may do anything at
-- all — the two are separate, and conflating them means a suspended admin
-- keeps their powers.
-- ---------------------------------------------------------------------
create type account_status as enum (
  'pending_verification', 'active', 'suspended', 'deactivated', 'banned'
);

alter table profiles
  add column if not exists status              account_status not null default 'pending_verification',
  add column if not exists email               citext,
  add column if not exists email_verified_at   timestamptz,
  add column if not exists suspended_reason    text,
  add column if not exists suspended_at        timestamptz,
  add column if not exists suspended_by        uuid references profiles(id) on delete set null,
  add column if not exists last_login_at       timestamptz,
  add column if not exists login_count         integer not null default 0,
  add column if not exists deactivated_at      timestamptz;

create index if not exists profiles_status_idx on profiles (status)
  where status <> 'active';
create index if not exists profiles_email_idx on profiles (email);

-- ---------------------------------------------------------------------
-- 3. PERMISSION MATRIX
-- Roles are coarse; permissions are what code actually checks. Keeping the
-- mapping in a table rather than in `if` statements means an admin can see
-- exactly who can do what, and adding a permission does not mean editing
-- twenty policies.
-- ---------------------------------------------------------------------
create table permissions (
  code        text primary key,
  category    text not null,
  description text not null
);

insert into permissions (code, category, description) values
  ('listings.read.all',     'listings', 'View every listing including drafts'),
  ('listings.write.own',    'listings', 'Create and edit their own business listings'),
  ('listings.publish',      'listings', 'Publish a listing so travellers can see it'),
  ('listings.moderate',     'listings', 'Approve, reject or suspend any listing'),
  ('bookings.read.own',     'bookings', 'View bookings for their own business'),
  ('bookings.read.all',     'bookings', 'View every booking on the platform'),
  ('bookings.manage',       'bookings', 'Cancel, amend and refund bookings'),
  ('payments.read',         'payments', 'View payment and payout records'),
  ('payments.refund',       'payments', 'Issue refunds'),
  ('content.write',         'content',  'Create and edit posts and pages'),
  ('content.publish',       'content',  'Publish content to the live site'),
  ('reviews.moderate',      'reviews',  'Approve, reject and remove reviews'),
  ('reviews.reply.own',     'reviews',  'Reply to reviews on their own listings'),
  ('leads.read',            'crm',      'View enquiries and leads'),
  ('leads.manage',          'crm',      'Assign and progress leads'),
  ('support.impersonate',   'support',  'View a dashboard as its owner, for support'),
  ('users.read',            'admin',    'View user accounts'),
  ('users.suspend',         'admin',    'Suspend and reinstate accounts'),
  ('users.assign_roles',    'admin',    'Change what role a user holds'),
  ('businesses.approve',    'admin',    'Approve business applications and claims'),
  ('settings.write',        'admin',    'Change site settings, theme and scripts'),
  ('analytics.read',        'admin',    'View platform analytics')
on conflict (code) do nothing;

create table role_permissions (
  role        user_role not null,
  permission  text not null references permissions(code) on delete cascade,
  primary key (role, permission)
);

alter table permissions enable row level security;
alter table permissions force row level security;
alter table role_permissions enable row level security;
alter table role_permissions force row level security;

